                          </label>
                          <input
                            type="text"
                            value={editingPreset.epc?.contractor || ""}
                            onChange={(e) =>
                              setEditingPreset({
                                ...editingPreset,
                                epc: { ...editingPreset.epc!, contractor: e.target.value },
                              })
                            }
                            placeholder="EPC Contractor name"
