                      >
                        <UserPlus size={20} />
                        Invite Team Members
                      </button>
                    )}
                  </div>
                )}

                {/* Invites Tab */}
                {activeTab === "invites" && canInvite && (
                  <div className="space-y-6">
                    <div className="bg-gradient-to-br from-purple-50 to-blue-50 rounded-xl p-6">
