                              {quote.pricing_data.notes}
                            </div>
                          )}
                        </div>
                      )}
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}

          {activeTab === "vendors" && (
            <div className="h-full flex">
              {/* Vendor List */}
              <div className="w-1/3 border-r h-full overflow-y-auto">
                <div className="p-4 border-b">
