                  </div>
                )}
              </div>
            </div>
          )}

          {activeTab === "products" && (
            <div className="h-full p-6">
              {selectedVendor ? (
                <div>
                  <h3 className="text-xl font-bold mb-4">Products from {selectedVendor.name}</h3>
