                    value={editingFormula.description}
                    rows={3}
                    className="w-full bg-gray-50 text-gray-800 px-4 py-2.5 rounded-xl border border-gray-200 focus:border-purple-400 focus:ring-2 focus:ring-purple-200 outline-none transition-all"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Data Source</label>
                  <input
                    type="text"
                    value={editingFormula.dataSource}
                    className="w-full bg-gray-50 text-gray-800 px-4 py-2.5 rounded-xl border border-gray-200 focus:border-purple-400 focus:ring-2 focus:ring-purple-200 outline-none transition-all"
                  />
                </div>

                <div className="flex gap-3 pt-4">
                  <button className="flex-1 bg-gradient-to-r from-emerald-500 to-teal-500 hover:from-emerald-600 hover:to-teal-600 text-white px-6 py-2.5 rounded-xl font-medium shadow-md shadow-emerald-500/20 transition-all">
                    💾 Save Changes
                  </button>
                  <button
                    onClick={() => setEditingFormula(null)}
                    className="flex-1 bg-gray-100 hover:bg-gray-200 text-gray-700 px-6 py-2.5 rounded-xl font-medium transition-all"
                  >
                    Cancel
                  </button>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default CalculationsAdmin;

/**
 * EquipmentPricingAdmin - Enhanced Equipment Pricing Dashboard
 * =============================================================
 * 
 * PURPOSE: Manage equipment_pricing_tiers table for all equipment types
 * 
 * EQUIPMENT TYPES:
 * - BESS, Solar, Inverter/PCS, Transformer, Switchgear
 * - Microgrid Controller, DC/AC Patch Panels, BMS, ESS Enclosure
 * - SCADA, EMS Software, EV Charger, Generator, Fuel Cell, Wind
 * 
 * FEATURES:
 * - View all equipment pricing by type and tier
 * - Edit prices with TrueQuote™ attribution
 * - Sync from market data sources
 * - Size-based tier management
 * - Manufacturer and model tracking
 * 
 * @created 2026-01-14
 */

import React, { useState, useEffect, useMemo } from 'react';
import {
  Settings,
  Database,
  Save,
  RefreshCw,
  CheckCircle,
  AlertTriangle,
  Search,
  ChevronDown,
  ChevronUp,
  Battery,
  Sun,
  Fuel,
  Zap,
  Wind,
  Cpu,
  Shield,
  Edit2,
  X,
  Loader2,
  ExternalLink,
  Download,
  Package,
  Server,
  Boxes,
  Monitor
} from 'lucide-react';
import { adminAuthService } from '@/services/adminAuthService';
import { clearAllPricingCaches } from '@/services/unifiedPricingService';
import equipmentPricingService, { 
  EQUIPMENT_TYPE_META,
  formatPriceForDisplay
} from '@/services/equipmentPricingTiersService';
import type { 
  EquipmentType, 
  PricingTier, 
  EquipmentPricingTier
} from '@/services/equipmentPricingTiersService';

// ============================================================================
// TYPES
// ============================================================================

interface EquipmentPricingAdminProps {
  isOpen: boolean;
  onClose: () => void;
}

// ============================================================================
// CATEGORY CONFIG - Maps to EQUIPMENT_TYPE_META with icons
// ============================================================================

const CATEGORY_ICONS: Record<EquipmentType, React.ReactNode> = {
  bess: <Battery className="w-5 h-5" />,
  solar: <Sun className="w-5 h-5" />,
  inverter_pcs: <Cpu className="w-5 h-5" />,
  transformer: <Zap className="w-5 h-5" />,
  switchgear: <Settings className="w-5 h-5" />,
  microgrid_controller: <Server className="w-5 h-5" />,
  dc_patch_panel: <Package className="w-5 h-5" />,
  ac_patch_panel: <Boxes className="w-5 h-5" />,
  bms: <Monitor className="w-5 h-5" />,
  ess_enclosure: <Package className="w-5 h-5" />,
  scada: <Server className="w-5 h-5" />,
  ems_software: <Monitor className="w-5 h-5" />,
  ev_charger: <Zap className="w-5 h-5" />,
  generator: <Fuel className="w-5 h-5" />,
  fuel_cell: <Cpu className="w-5 h-5" />,
  wind: <Wind className="w-5 h-5" />
};

const TIER_COLORS: Record<PricingTier, string> = {
  economy: 'slate',
  standard: 'cyan',
  premium: 'purple',
  enterprise: 'amber'
};

// ============================================================================
// COMPONENT
// ============================================================================

export const EquipmentPricingAdmin: React.FC<EquipmentPricingAdminProps> = ({ isOpen, onClose }) => {
  // State
  const [pricingData, setPricingData] = useState<Record<EquipmentType, EquipmentPricingTier[]>>({} as any);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedType, setSelectedType] = useState<EquipmentType | 'all'>('all');
  const [selectedTier, setSelectedTier] = useState<PricingTier | 'all'>('all');
  const [expandedTypes, setExpandedTypes] = useState<Set<EquipmentType>>(new Set());
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editValues, setEditValues] = useState<Partial<EquipmentPricingTier>>({});
  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved' | 'error'>('idle');
  const [showAddModal, setShowAddModal] = useState(false);
  const [marketSyncStatus, setMarketSyncStatus] = useState<Record<EquipmentType, 'idle' | 'syncing' | 'done' | 'error'>>({} as any);

  // Permissions
  const canEdit = adminAuthService.hasPermission('edit_pricing');
  const canSave = adminAuthService.hasPermission('save_pricing');

  // Load data on mount
  useEffect(() => {
    if (isOpen) {
      loadPricingData();
    }
  }, [isOpen]);

  // ============================================================================
  // DATA LOADING
  // ============================================================================

  const loadPricingData = async () => {
    setLoading(true);
    setError(null);

    try {
      const data = await equipmentPricingService.getAllEquipmentPricing();
      setPricingData(data);
    } catch (err: any) {
      console.error('Failed to load equipment pricing:', err);
      setError(err.message || 'Failed to load pricing data');
    } finally {
      setLoading(false);
    }
  };

  // ============================================================================
  // FILTERING
  // ============================================================================

  const filteredData = useMemo(() => {
    const result: Record<EquipmentType, EquipmentPricingTier[]> = {} as any;

    for (const [type, tiers] of Object.entries(pricingData)) {
      // Type filter
      if (selectedType !== 'all' && type !== selectedType) continue;

      const filteredTiers = tiers.filter(tier => {
        // Tier filter
        if (selectedTier !== 'all' && tier.tier_name !== selectedTier) return false;

        // Search filter
        if (searchTerm) {
          const search = searchTerm.toLowerCase();
          return (
            tier.manufacturer?.toLowerCase().includes(search) ||
            tier.model?.toLowerCase().includes(search) ||
            tier.data_source?.toLowerCase().includes(search) ||
            type.includes(search)
          );
        }
        return true;
      });

      if (filteredTiers.length > 0) {
        result[type as EquipmentType] = filteredTiers;
      }
    }

    return result;
  }, [pricingData, selectedType, selectedTier, searchTerm]);

  // Stats
  const stats = useMemo(() => {
    let totalTiers = 0;
    let highConfidence = 0;
    const types = Object.keys(pricingData).length;

    for (const tiers of Object.values(pricingData)) {
      totalTiers += tiers.length;
      highConfidence += tiers.filter(t => t.confidence_level === 'high').length;
    }

    return { types, totalTiers, highConfidence };
  }, [pricingData]);

  // ============================================================================
  // EDITING
  // ============================================================================

  const startEditing = (tier: EquipmentPricingTier) => {
    if (!canEdit) return;
    setEditingId(tier.id);
    setEditValues({
      base_price: tier.base_price,
      manufacturer: tier.manufacturer,
      model: tier.model,
      data_source: tier.data_source,
      source_url: tier.source_url,
      confidence_level: tier.confidence_level,
      notes: tier.notes
    });
  };

  const cancelEditing = () => {
    setEditingId(null);
    setEditValues({});
  };

  const saveEdits = async () => {
    if (!editingId || !canSave) return;

    setSaveStatus('saving');

    try {
      const success = await equipmentPricingService.updateEquipmentPricing(editingId, {
        ...editValues,
        source_date: new Date().toISOString().split('T')[0]
      } as any);

      if (!success) throw new Error('Update failed');

      // Clear caches and reload
      await clearAllPricingCaches();
      await loadPricingData();

      setSaveStatus('saved');
      setEditingId(null);
      setEditValues({});

      setTimeout(() => setSaveStatus('idle'), 2000);
    } catch (err: any) {
      console.error('Failed to save:', err);
      setSaveStatus('error');
    }
  };

  // ============================================================================
  // MARKET SYNC
  // ============================================================================

  const syncFromMarket = async (type: EquipmentType) => {
    setMarketSyncStatus(prev => ({ ...prev, [type]: 'syncing' }));

    try {
      const result = await equipmentPricingService.syncPricingFromMarketData(type);

      if (result.errors.length > 0) {
        console.warn(`Sync warnings for ${type}:`, result.errors);
      }

      await loadPricingData();
      setMarketSyncStatus(prev => ({ ...prev, [type]: 'done' }));

      setTimeout(() => {
        setMarketSyncStatus(prev => ({ ...prev, [type]: 'idle' }));
      }, 2000);
    } catch (err) {
      console.error(`Failed to sync ${type}:`, err);
      setMarketSyncStatus(prev => ({ ...prev, [type]: 'error' }));
    }
  };

  // ============================================================================
  // TOGGLE EXPAND
  // ============================================================================

  const toggleExpand = (type: EquipmentType) => {
    setExpandedTypes(prev => {
      const next = new Set(prev);
      if (next.has(type)) {
        next.delete(type);
      } else {
        next.add(type);
      }
      return next;
    });
  };

  // ============================================================================
  // RENDER HELPERS
  // ============================================================================

  const getConfidenceBadge = (level: string | null) => {
    switch (level) {
      case 'high':
        return <span className="px-2 py-0.5 bg-emerald-500/20 text-emerald-400 text-xs rounded-full">✓ High</span>;
      case 'medium':
        return <span className="px-2 py-0.5 bg-amber-500/20 text-amber-400 text-xs rounded-full">~ Medium</span>;
      case 'low':
        return <span className="px-2 py-0.5 bg-red-500/20 text-red-400 text-xs rounded-full">⚠ Low</span>;
      case 'estimate':
        return <span className="px-2 py-0.5 bg-slate-500/20 text-slate-400 text-xs rounded-full">Est.</span>;
      default:
        return null;
    }
  };

  const getTierBadge = (tier: PricingTier) => {
    const colors = {
      economy: 'bg-slate-500/20 text-slate-400',
      standard: 'bg-cyan-500/20 text-cyan-400',
      premium: 'bg-purple-500/20 text-purple-400',
      enterprise: 'bg-amber-500/20 text-amber-400'
    };
    return (
      <span className={`px-2 py-0.5 text-xs rounded-full ${colors[tier]}`}>
        {tier.charAt(0).toUpperCase() + tier.slice(1)}
      </span>
    );
  };

  // ============================================================================
  // RENDER
  // ============================================================================

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
      <div className="bg-slate-900 rounded-2xl w-full max-w-7xl max-h-[95vh] overflow-hidden border border-cyan-500/30 shadow-2xl flex flex-col">
        {/* Header */}
        <div className="p-6 border-b border-slate-700 flex items-center justify-between shrink-0">
          <div className="flex items-center gap-4">
            <div className="p-3 bg-cyan-500/20 rounded-xl">
              <Package className="w-6 h-6 text-cyan-400" />
            </div>
            <div>
              <h2 className="text-2xl font-bold text-white">Equipment Pricing Tiers</h2>
              <p className="text-slate-400 text-sm">
                {stats.types} equipment types • {stats.totalTiers} pricing tiers • {stats.highConfidence} high confidence
              </p>
            </div>
          </div>

          <div className="flex items-center gap-3">
            {/* TrueQuote Badge */}
            <div className="flex items-center gap-2 px-4 py-2 bg-emerald-500/10 border border-emerald-500/30 rounded-full">
              <Shield className="w-4 h-4 text-emerald-400" />
              <span className="text-emerald-400 text-sm font-medium">TrueQuote™</span>
            </div>

            {/* Refresh */}
            <button
              onClick={loadPricingData}
              className="p-2 text-slate-400 hover:text-white hover:bg-slate-700 rounded-lg transition-colors"
              title="Refresh"
            >
              <RefreshCw className={`w-5 h-5 ${loading ? 'animate-spin' : ''}`} />
            </button>

            {/* Close */}
            <button
              onClick={onClose}
              className="p-2 text-slate-400 hover:text-white hover:bg-slate-700 rounded-lg transition-colors"
            >
              <X className="w-5 h-5" />
            </button>
          </div>
        </div>

        {/* Filters */}
        <div className="p-4 border-b border-slate-700 flex items-center gap-4 flex-wrap shrink-0">
          {/* Search */}
          <div className="relative flex-1 min-w-[200px]">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500" />
            <input
              type="text"
              placeholder="Search by manufacturer, model, source..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pl-10 pr-4 py-2 bg-slate-800 border border-slate-600 rounded-lg text-white placeholder-slate-500 focus:outline-none focus:border-cyan-500"
            />
          </div>

          {/* Equipment Type Filter */}
          <select
            value={selectedType}
            onChange={(e) => setSelectedType(e.target.value as EquipmentType | 'all')}
            className="px-4 py-2 bg-slate-800 border border-slate-600 rounded-lg text-white focus:outline-none focus:border-cyan-500"
          >
            <option value="all">All Equipment Types</option>
            {Object.entries(EQUIPMENT_TYPE_META).map(([key, meta]) => (
              <option key={key} value={key}>
                {meta.icon} {meta.label}
              </option>
            ))}
          </select>

          {/* Tier Filter */}
          <select
            value={selectedTier}
            onChange={(e) => setSelectedTier(e.target.value as PricingTier | 'all')}
            className="px-4 py-2 bg-slate-800 border border-slate-600 rounded-lg text-white focus:outline-none focus:border-cyan-500"
          >
            <option value="all">All Tiers</option>
            <option value="economy">Economy</option>
            <option value="standard">Standard</option>
            <option value="premium">Premium</option>
            <option value="enterprise">Enterprise</option>
          </select>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto p-6">
          {loading ? (
            <div className="flex items-center justify-center py-12">
              <Loader2 className="w-8 h-8 text-cyan-500 animate-spin" />
            </div>
          ) : error ? (
            <div className="text-center py-12">
              <AlertTriangle className="w-12 h-12 text-red-400 mx-auto mb-4" />
              <p className="text-red-400">{error}</p>
              <button
                onClick={loadPricingData}
                className="mt-4 px-4 py-2 bg-slate-700 text-white rounded-lg hover:bg-slate-600"
              >
                Retry
              </button>
            </div>
          ) : Object.keys(filteredData).length === 0 ? (
            <div className="text-center py-12">
              <Database className="w-12 h-12 text-slate-500 mx-auto mb-4" />
              <p className="text-slate-400">No pricing data found</p>
              <p className="text-slate-500 text-sm mt-2">Run the migration to seed initial data</p>
            </div>
          ) : (
            <div className="space-y-6">
              {Object.entries(filteredData).map(([type, tiers]) => {
                const meta = EQUIPMENT_TYPE_META[type as EquipmentType];
                const isExpanded = expandedTypes.has(type as EquipmentType);
                const syncStatus = marketSyncStatus[type as EquipmentType];

                return (
                  <div
                    key={type}
                    className={`bg-slate-800/50 border rounded-xl overflow-hidden transition-all ${
                      isExpanded ? 'border-cyan-500/50' : 'border-slate-700'
                    }`}
                  >
                    {/* Equipment Type Header */}
                    <div
                      className="p-4 flex items-center gap-4 cursor-pointer hover:bg-slate-700/30"
                      onClick={() => toggleExpand(type as EquipmentType)}
                    >
                      <div className="p-2 bg-cyan-500/20 rounded-lg text-cyan-400">
                        {CATEGORY_ICONS[type as EquipmentType]}
                      </div>

                      <div className="flex-1">
                        <h3 className="text-white font-semibold flex items-center gap-2">
                          {meta?.icon} {meta?.label || type}
                        </h3>
                        <p className="text-slate-400 text-sm">
                          {tiers.length} pricing tier{tiers.length !== 1 ? 's' : ''}
                        </p>
                      </div>

                      {/* Quick stats */}
                      <div className="hidden md:flex items-center gap-2">
                        {tiers.some(t => t.tier_name === 'standard') && (
                          <span className="text-xs text-slate-500">
                            Standard: {formatPriceForDisplay(
                              tiers.find(t => t.tier_name === 'standard')?.base_price || 0,
                              tiers.find(t => t.tier_name === 'standard')?.price_unit as any || 'per_unit'
                            )}
                          </span>
                        )}
                      </div>

                      {/* Market Sync Button */}
                      {canEdit && (
                        <button
                          onClick={(e) => {
                            e.stopPropagation();
                            syncFromMarket(type as EquipmentType);
                          }}
                          disabled={syncStatus === 'syncing'}
                          className={`p-2 rounded-lg transition-colors ${
                            syncStatus === 'syncing' ? 'bg-amber-500/20 text-amber-400' :
                            syncStatus === 'done' ? 'bg-emerald-500/20 text-emerald-400' :
                            syncStatus === 'error' ? 'bg-red-500/20 text-red-400' :
                            'bg-slate-700 text-slate-400 hover:text-white hover:bg-slate-600'
                          }`}
                          title="Sync from market data"
                        >
                          {syncStatus === 'syncing' ? (
                            <Loader2 className="w-4 h-4 animate-spin" />
                          ) : syncStatus === 'done' ? (
                            <CheckCircle className="w-4 h-4" />
                          ) : (
                            <Download className="w-4 h-4" />
                          )}
                        </button>
                      )}

                      <div className="text-slate-400">
                        {isExpanded ? <ChevronUp className="w-5 h-5" /> : <ChevronDown className="w-5 h-5" />}
                      </div>
                    </div>

                    {/* Expanded Pricing Tiers */}
                    {isExpanded && (
                      <div className="border-t border-slate-700">
                        <table className="w-full">
                          <thead className="bg-slate-800/50">
                            <tr className="text-xs text-slate-500">
                              <th className="px-4 py-3 text-left">Tier</th>
                              <th className="px-4 py-3 text-left">Manufacturer / Model</th>
                              <th className="px-4 py-3 text-right">Price</th>
                              <th className="px-4 py-3 text-left">Size Range</th>
                              <th className="px-4 py-3 text-left">Source</th>
                              <th className="px-4 py-3 text-center">Confidence</th>
                              {canEdit && <th className="px-4 py-3 text-right">Actions</th>}
                            </tr>
                          </thead>
                          <tbody>
                            {tiers.map(tier => {
                              const isEditing = editingId === tier.id;

                              return (
                                <tr key={tier.id} className="border-t border-slate-700/50 hover:bg-slate-700/20">
                                  <td className="px-4 py-3">
                                    {getTierBadge(tier.tier_name as PricingTier)}
                                  </td>
                                  <td className="px-4 py-3">
                                    {isEditing ? (
                                      <div className="flex gap-2">
                                        <input
                                          type="text"
                                          value={editValues.manufacturer || ''}
                                          onChange={(e) => setEditValues(v => ({ ...v, manufacturer: e.target.value }))}
                                          placeholder="Manufacturer"
                                          className="w-24 px-2 py-1 bg-slate-700 border border-slate-600 rounded text-sm text-white"
                                        />
                                        <input
                                          type="text"
                                          value={editValues.model || ''}
                                          onChange={(e) => setEditValues(v => ({ ...v, model: e.target.value }))}
                                          placeholder="Model"
                                          className="w-32 px-2 py-1 bg-slate-700 border border-slate-600 rounded text-sm text-white"
                                        />
                                      </div>
                                    ) : (
                                      <div>
                                        <div className="text-white font-medium">{tier.manufacturer || 'Generic'}</div>
                                        {tier.model && <div className="text-slate-400 text-sm">{tier.model}</div>}
                                      </div>
                                    )}
                                  </td>
                                  <td className="px-4 py-3 text-right">
                                    {isEditing ? (
                                      <input
                                        type="number"
                                        value={editValues.base_price || 0}
                                        onChange={(e) => setEditValues(v => ({ ...v, base_price: parseFloat(e.target.value) }))}
                                        className="w-24 px-2 py-1 bg-slate-700 border border-slate-600 rounded text-sm text-white text-right"
                                      />
                                    ) : (
                                      <span className="text-cyan-400 font-mono font-semibold">
                                        {formatPriceForDisplay(tier.base_price, tier.price_unit as any)}
                                      </span>
                                    )}
                                  </td>
                                  <td className="px-4 py-3 text-slate-400 text-sm">
                                    {tier.size_min !== null || tier.size_max !== null ? (
                                      `${tier.size_min || 0} - ${tier.size_max || '∞'} ${tier.size_unit || ''}`
                                    ) : (
                                      <span className="text-slate-500">All sizes</span>
                                    )}
                                  </td>
                                  <td className="px-4 py-3">
                                    <div className="flex items-center gap-2">
                                      <span className="text-slate-400 text-sm truncate max-w-[150px]">
                                        {tier.data_source || 'Internal'}
                                      </span>
                                      {tier.source_url && (
                                        <a
                                          href={tier.source_url}
                                          target="_blank"
                                          rel="noopener noreferrer"
                                          className="text-cyan-400 hover:text-cyan-300"
                                        >
                                          <ExternalLink className="w-3 h-3" />
                                        </a>
                                      )}
                                    </div>
                                  </td>
                                  <td className="px-4 py-3 text-center">
                                    {getConfidenceBadge(tier.confidence_level)}
                                  </td>
                                  {canEdit && (
                                    <td className="px-4 py-3 text-right">
                                      {isEditing ? (
                                        <div className="flex items-center justify-end gap-2">
                                          <button
                                            onClick={cancelEditing}
                                            className="p-1.5 text-slate-400 hover:text-white hover:bg-slate-600 rounded"
                                          >
                                            <X className="w-4 h-4" />
                                          </button>
                                          <button
                                            onClick={saveEdits}
                                            disabled={saveStatus === 'saving'}
                                            className="p-1.5 text-emerald-400 hover:text-emerald-300 hover:bg-emerald-500/20 rounded"
                                          >
                                            {saveStatus === 'saving' ? (
                                              <Loader2 className="w-4 h-4 animate-spin" />
                                            ) : (
                                              <Save className="w-4 h-4" />
                                            )}
                                          </button>
                                        </div>
                                      ) : (
                                        <button
                                          onClick={() => startEditing(tier)}
                                          className="p-1.5 text-slate-400 hover:text-white hover:bg-slate-600 rounded"
                                        >
                                          <Edit2 className="w-4 h-4" />
                                        </button>
                                      )}
                                    </td>
                                  )}
                                </tr>
                              );
                            })}
                          </tbody>
                        </table>
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="p-4 border-t border-slate-700 flex items-center justify-between text-sm text-slate-500 shrink-0">
          <div className="flex items-center gap-2">
            <Shield className="w-4 h-4 text-emerald-400" />
            <span>Pricing from NREL ATB 2024, vendor quotes, and verified market data</span>
          </div>
          <div>
            {saveStatus === 'saved' && (
              <span className="text-emerald-400 flex items-center gap-1">
                <CheckCircle className="w-4 h-4" /> Saved successfully
              </span>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default EquipmentPricingAdmin;

/**
 * MARKET INTELLIGENCE DASHBOARD
 * =============================
 * 
 * Displays market inference analysis results:
 * - Market and price trends
 * - BESS configuration patterns
 * - Customer decision indicators
 * - Emerging opportunities
 * - Industry adoption rates
 * 
 * Created: January 3, 2025
 */

import React, { useState, useEffect } from 'react';
import { TrendingUp, TrendingDown, Minus, BarChart3, Zap, Lightbulb, Building2, RefreshCw, AlertCircle, DollarSign, Activity, Target, ExternalLink } from 'lucide-react';
import { runMarketInference, type MarketInference, type MarketTrend, type BESSConfigurationPattern, type CustomerDecisionIndicator, type EmergingOpportunity, type IndustryAdoptionRate, type PricingUpdateRecommendation } from '@/services/marketInferenceEngine';
import { supabase } from '@/services/supabaseClient';
import MarketIntelligenceDetailModal from './MarketIntelligenceDetailModal';

const MarketIntelligenceDashboard: React.FC = () => {
  const [inference, setInference] = useState<MarketInference | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<'overview' | 'trends' | 'configs' | 'indicators' | 'opportunities' | 'adoption' | 'pricing'>('overview');
  const [pendingApprovals, setPendingApprovals] = useState<any[]>([]);
  const [selectedItem, setSelectedItem] = useState<{
    type: 'trend' | 'config' | 'indicator' | 'opportunity' | 'adoption' | 'pricing';
    data: any;
  } | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);

  useEffect(() => {
    loadLatestInference();
    loadPendingApprovals();
  }, []);

  const loadLatestInference = async () => {
    try {
      const { data, error: fetchError } = await supabase
        .from('market_inferences')
        .select('*')
        .order('analysis_date', { ascending: false })
        .limit(1)
        .maybeSingle();

      if (fetchError) {
        // Check if it's a "table doesn't exist" error
        if (fetchError.message?.includes('does not exist') || fetchError.code === '42P01') {
          setError('Database table does not exist. Please run the migration: database/migrations/20250103_market_inference_tables.sql');
          return;
        }
        // For other errors, just log and continue (table might be empty)
        console.warn('Could not load inference:', fetchError.message);
        return;
      }

      if (data) {
        // If loaded data is empty or insufficient, generate sample data
        const hasData = (data.market_trends?.length || 0) > 0 && 
                       (data.bess_configurations?.length || 0) > 0 && 
                       (data.industry_adoption?.length || 0) > 0;

        if (!hasData) {
          // Data is incomplete - don't show placeholder data
          console.log('📊 Existing data is incomplete. Run analysis to generate insights.');
        } else {
          setInference({
            analysisDate: data.analysis_date,
            marketTrends: data.market_trends || [],
            bessConfigurations: data.bess_configurations || [],
            decisionIndicators: data.decision_indicators || [],
            emergingOpportunities: data.emerging_opportunities || [],
            industryAdoption: data.industry_adoption || [],
            overallMarketSentiment: data.overall_sentiment,
            confidence: data.confidence,
            dataPointsAnalyzed: data.data_points_analyzed,
            sources: data.sources || [],
            requiresPricingUpdate: data.requires_pricing_update,
            pricingUpdateRecommendations: data.pricing_update_recommendations || [],
          });
        }
      } else {
        // No data in database - don't show placeholder data
        console.log('📊 No existing inference data found. Run analysis to generate insights.');
      }
    } catch (err) {
      console.error('Error loading inference:', err);
      const errorMessage = err instanceof Error ? err.message : 'Failed to load market intelligence';
      if (errorMessage.includes('does not exist')) {
        setError('Database table does not exist. Please run the migration: database/migrations/20250103_market_inference_tables.sql');
      } else {
        setError(errorMessage);
      }
    }
  };

  const loadPendingApprovals = async () => {
    try {
      const { data } = await supabase
        .from('pricing_update_approvals')
        .select('*')
        .eq('status', 'pending')
        .order('requested_at', { ascending: false });

      setPendingApprovals(data || []);
    } catch (err) {
      console.error('Error loading approvals:', err);
    }
  };

  const runAnalysis = async () => {
    setLoading(true);
    setError(null);
    try {
      const result = await runMarketInference(90);
      setInference(result);
      await loadPendingApprovals();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to run analysis');
    } finally {
      setLoading(false);
    }
  };

  const handleItemClick = (type: 'trend' | 'config' | 'indicator' | 'opportunity' | 'adoption' | 'pricing', data: any) => {
    console.log('🔍 Opening detail modal:', { type, data });
    if (!data) {
      console.error('❌ No data provided to modal!');
      alert('No data available for this item.');
      return;
    }
    setSelectedItem({ type, data });
    setIsModalOpen(true);
  };

  const handleEdit = async (updatedData: any) => {
    if (!inference || !selectedItem) return;

    try {
      // Update the inference object
      const updatedInference = { ...inference };

      switch (selectedItem.type) {
        case 'trend':
          updatedInference.marketTrends = inference.marketTrends.map((t: MarketTrend, idx: number) => 
            t === selectedItem.data ? updatedData : t
          );
          break;
        case 'config':
          updatedInference.bessConfigurations = inference.bessConfigurations.map((c: BESSConfigurationPattern, idx: number) => 
            c === selectedItem.data ? updatedData : c
          );
          break;
        case 'indicator':
          updatedInference.decisionIndicators = inference.decisionIndicators.map((i: CustomerDecisionIndicator, idx: number) => 
            i === selectedItem.data ? updatedData : i
          );
          break;
        case 'opportunity':
          updatedInference.emergingOpportunities = inference.emergingOpportunities.map((o: EmergingOpportunity, idx: number) => 
            o === selectedItem.data ? updatedData : o
          );
          break;
        case 'adoption':
          updatedInference.industryAdoption = inference.industryAdoption.map((a: IndustryAdoptionRate, idx: number) => 
            a === selectedItem.data ? updatedData : a
          );
          break;
        case 'pricing':
          updatedInference.pricingUpdateRecommendations = (inference.pricingUpdateRecommendations || []).map((p: PricingUpdateRecommendation, idx: number) => 
            p === selectedItem.data ? updatedData : p
          );
          break;
      }

      // Save to database
      const { error } = await supabase
        .from('market_inferences')
        .update({
          market_trends: updatedInference.marketTrends,
          bess_configurations: updatedInference.bessConfigurations,
          decision_indicators: updatedInference.decisionIndicators,
          emerging_opportunities: updatedInference.emergingOpportunities,
          industry_adoption: updatedInference.industryAdoption,
          pricing_update_recommendations: updatedInference.pricingUpdateRecommendations,
          updated_at: new Date().toISOString(),
        })
        .eq('analysis_date', new Date(updatedInference.analysisDate).toISOString().split('T')[0]);

      if (error) throw error;

      setInference(updatedInference);
      setIsModalOpen(false);
      setSelectedItem(null);
    } catch (err) {
      console.error('Error updating inference:', err);
      alert('Failed to save changes. Please try again.');
    }
  };

  const handleDelete = async () => {
    if (!inference || !selectedItem || !confirm('Are you sure you want to delete this item?')) return;

    try {
      const updatedInference = { ...inference };

      switch (selectedItem.type) {
        case 'trend':
          updatedInference.marketTrends = inference.marketTrends.filter((t: MarketTrend) => t !== selectedItem.data);
          break;
        case 'config':
          updatedInference.bessConfigurations = inference.bessConfigurations.filter((c: BESSConfigurationPattern) => c !== selectedItem.data);
          break;
        case 'indicator':
          updatedInference.decisionIndicators = inference.decisionIndicators.filter((i: CustomerDecisionIndicator) => i !== selectedItem.data);
          break;
        case 'opportunity':
          updatedInference.emergingOpportunities = inference.emergingOpportunities.filter((o: EmergingOpportunity) => o !== selectedItem.data);
          break;
        case 'adoption':
          updatedInference.industryAdoption = inference.industryAdoption.filter((a: IndustryAdoptionRate) => a !== selectedItem.data);
          break;
        case 'pricing':
          updatedInference.pricingUpdateRecommendations = (inference.pricingUpdateRecommendations || []).filter((p: PricingUpdateRecommendation) => p !== selectedItem.data);
          break;
      }

      // Save to database
      const { error } = await supabase
        .from('market_inferences')
        .update({
          market_trends: updatedInference.marketTrends,
          bess_configurations: updatedInference.bessConfigurations,
          decision_indicators: updatedInference.decisionIndicators,
          emerging_opportunities: updatedInference.emergingOpportunities,
          industry_adoption: updatedInference.industryAdoption,
          pricing_update_recommendations: updatedInference.pricingUpdateRecommendations,
          updated_at: new Date().toISOString(),
        })
        .eq('analysis_date', new Date(updatedInference.analysisDate).toISOString().split('T')[0]);

      if (error) throw error;

      setInference(updatedInference);
      setIsModalOpen(false);
      setSelectedItem(null);
    } catch (err) {
      console.error('Error deleting item:', err);
      alert('Failed to delete item. Please try again.');
    }
  };

  const getTrendIcon = (direction: string) => {
    switch (direction) {
      case 'increasing':
        return <TrendingUp className="w-5 h-5 text-green-500" />;
      case 'decreasing':
        return <TrendingDown className="w-5 h-5 text-red-500" />;
      default:
        return <Minus className="w-5 h-5 text-gray-500" />;
    }
  };

  const getSentimentColor = (sentiment: string) => {
    switch (sentiment) {
      case 'bullish':
        return 'text-green-600 bg-green-50 border-green-200';
      case 'bearish':
        return 'text-red-600 bg-red-50 border-red-200';
      default:
        return 'text-gray-600 bg-gray-50 border-gray-200';
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 via-blue-50 to-purple-50 p-6">
      {/* Header */}
      <div className="mb-6">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-3xl font-bold bg-gradient-to-r from-purple-700 via-indigo-700 to-purple-700 bg-clip-text text-transparent">
              Market Intelligence Dashboard
            </h1>
            <p className="text-gray-600 mt-1">
              AI-powered market analysis from signals, news, and installations
            </p>
          </div>
          <button
            onClick={runAnalysis}
            disabled={loading}
            className="flex items-center gap-2 px-4 py-2 bg-gradient-to-r from-purple-700 to-slate-600 text-white rounded-lg hover:from-purple-800 hover:to-slate-700 disabled:opacity-50 disabled:cursor-not-allowed shadow-lg"
          >
            <RefreshCw className={`w-4 h-4 ${loading ? 'animate-spin' : ''}`} />
            {loading ? 'Analyzing...' : 'Run Analysis'}
          </button>
        </div>
      </div>

      {error && (
        <div className="mb-6 p-4 bg-red-50 border border-red-200 rounded-lg text-red-700">
          {error}
        </div>
      )}

      {/* Pending Approvals Alert */}
      {pendingApprovals.length > 0 && (
        <div className="mb-6 p-4 bg-amber-50 border border-amber-200 rounded-lg">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              <AlertCircle className="w-5 h-5 text-amber-600" />
              <span className="font-semibold text-amber-800">
                {pendingApprovals.length} Pricing Update{pendingApprovals.length > 1 ? 's' : ''} Pending Approval
              </span>
            </div>
            <button
              onClick={() => setActiveTab('pricing')}
              className="text-amber-700 hover:text-amber-900 font-medium"
            >
              Review →
            </button>
          </div>
        </div>
      )}

      {!inference && !loading && (
        <div className="text-center py-12 bg-white rounded-lg shadow-sm border border-gray-200">
          <BarChart3 className="w-16 h-16 text-gray-400 mx-auto mb-4" />
          <h3 className="text-lg font-medium text-gray-900 mb-2">No Analysis Available</h3>
          <p className="text-gray-600 mb-4">Run your first market analysis to see insights</p>
          <button
            onClick={runAnalysis}
            className="px-4 py-2 bg-purple-700 text-white rounded-lg hover:bg-purple-800"
          >
            Run Analysis
          </button>
        </div>
      )}

      {inference && (
        <>
          {/* Overview Cards */}
          <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6">
            <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-4">
              <div className="flex items-center justify-between mb-2">
                <span className="text-sm text-gray-600">Market Sentiment</span>
                <Activity className="w-4 h-4 text-gray-400" />
              </div>
              <div className={`text-2xl font-bold mb-1 ${getSentimentColor(inference.overallMarketSentiment).split(' ')[0]}`}>
                {inference.overallMarketSentiment.charAt(0).toUpperCase() + inference.overallMarketSentiment.slice(1)}
              </div>
              <div className="text-xs text-gray-500">
                Confidence: {(inference.confidence * 100).toFixed(0)}%
              </div>
            </div>

            <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-4">
              <div className="flex items-center justify-between mb-2">
                <span className="text-sm text-gray-600">Data Points</span>
                <BarChart3 className="w-4 h-4 text-gray-400" />
              </div>
              <div className="text-2xl font-bold text-gray-900">
                {inference.dataPointsAnalyzed.toLocaleString()}
              </div>
              <div className="text-xs text-gray-500">
                {inference.sources.length} sources
              </div>
            </div>

            <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-4">
              <div className="flex items-center justify-between mb-2">
                <span className="text-sm text-gray-600">Market Trends</span>
                <TrendingUp className="w-4 h-4 text-gray-400" />
              </div>
              <div className="text-2xl font-bold text-gray-900">
                {inference.marketTrends.length}
              </div>
              <div className="text-xs text-gray-500">
                Active trends
              </div>
            </div>

            <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-4">
              <div className="flex items-center justify-between mb-2">
                <span className="text-sm text-gray-600">Pricing Updates</span>
                <DollarSign className="w-4 h-4 text-gray-400" />
              </div>
              <div className="text-2xl font-bold text-gray-900">
                {inference.pricingUpdateRecommendations?.length || 0}
              </div>
              <div className="text-xs text-gray-500">
                {inference.requiresPricingUpdate ? 'Pending' : 'None'}
              </div>
            </div>
          </div>

          {/* Navigation Tabs */}
          <div className="bg-white rounded-lg shadow-sm border border-gray-200 mb-6">
            <div className="flex border-b border-gray-200">
              {[
                { key: 'overview', label: 'Overview', icon: BarChart3 },
                { key: 'trends', label: 'Market Trends', icon: TrendingUp },
                { key: 'configs', label: 'BESS Configs', icon: Zap },
                { key: 'indicators', label: 'Decision Indicators', icon: Target },
                { key: 'opportunities', label: 'Opportunities', icon: Lightbulb },
                { key: 'adoption', label: 'Industry Adoption', icon: Building2 },
                { key: 'pricing', label: 'Pricing Updates', icon: DollarSign },
              ].map(tab => (
                <button
                  key={tab.key}
                  onClick={() => setActiveTab(tab.key as any)}
                  className={`flex items-center gap-2 px-4 py-3 border-b-2 transition-colors ${
                    activeTab === tab.key
                      ? 'border-purple-700 text-purple-700 font-medium'
                      : 'border-transparent text-gray-600 hover:text-gray-900 hover:border-gray-300'
                  }`}
                >
                  <tab.icon className="w-4 h-4" />
                  {tab.label}
                </button>
              ))}
            </div>

            <div className="p-6">
              {activeTab === 'overview' && <OverviewTab inference={inference} onItemClick={handleItemClick} />}
              {activeTab === 'trends' && <TrendsTab trends={inference.marketTrends} onItemClick={handleItemClick} />}
              {activeTab === 'configs' && <ConfigsTab configs={inference.bessConfigurations} onItemClick={handleItemClick} />}
              {activeTab === 'indicators' && <IndicatorsTab indicators={inference.decisionIndicators} onItemClick={handleItemClick} />}
              {activeTab === 'opportunities' && <OpportunitiesTab opportunities={inference.emergingOpportunities} onItemClick={handleItemClick} />}
              {activeTab === 'adoption' && <AdoptionTab adoption={inference.industryAdoption} onItemClick={handleItemClick} />}
              {activeTab === 'pricing' && (
                <PricingTab 
                  recommendations={inference.pricingUpdateRecommendations || []}
                  pendingApprovals={pendingApprovals}
                  onApprovalUpdate={loadPendingApprovals}
                  onItemClick={handleItemClick}
                />
              )}
            </div>
          </div>
        </>
      )}

      {/* Detail Modal */}
      {selectedItem && (
        <MarketIntelligenceDetailModal
          isOpen={isModalOpen}
          onClose={() => {
            setIsModalOpen(false);
            setSelectedItem(null);
          }}
          type={selectedItem.type}
          data={selectedItem.data}
          onEdit={handleEdit}
          onDelete={handleDelete}
        />
      )}
    </div>
  );
};

