/**
 * MIGRATION GUIDE: Converting Components to Use Database Service
 * Example showing how to convert existing components from static templates to database
 */

import React, { useState, useEffect } from 'react';
import { useCaseService, type UseCaseWithConfiguration } from '../../services/useCaseService';

// =================== BEFORE: Static Template Approach ===================
/*
import { USE_CASE_TEMPLATES } from '../data/useCaseTemplates';

const UseCaseSelector = () => {
  const [useCases] = useState(USE_CASE_TEMPLATES);
  const [filteredCases, setFilteredCases] = useState(USE_CASE_TEMPLATES);

  const filterByCategory = (category: string) => {
    setFilteredCases(useCases.filter(uc => uc.category === category));
  };

  return (
    <div>
      {filteredCases.map(useCase => (
        <div key={useCase.id}>
          <h3>{useCase.name}</h3>
          <p>{useCase.description}</p>
        </div>
      ))}
    </div>
  );
};
*/

// =================== AFTER: Database Service Approach ===================

interface UseCaseSelectorProps {
  onUseCaseSelect?: (useCase: UseCaseWithConfiguration) => void;
  category?: string;
  tier?: string;
}

export const UseCaseSelector: React.FC<UseCaseSelectorProps> = ({
  onUseCaseSelect,
  category,
  tier
}) => {
  const [useCases, setUseCases] = useState<UseCaseWithConfiguration[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [filteredCases, setFilteredCases] = useState<UseCaseWithConfiguration[]>([]);

  // Load use cases from database on component mount
  useEffect(() => {
    const loadUseCases = async () => {
      try {
        setLoading(true);
        let result: UseCaseWithConfiguration[];

        if (category) {
          result = await useCaseService.getUseCasesByCategory(category);
        } else if (tier) {
          result = await useCaseService.getUseCasesByTier(tier);
        } else {
          result = await useCaseService.getAllUseCases();
        }

        setUseCases(result);
        setFilteredCases(result);
      } catch (err) {
        console.error('Failed to load use cases:', err);
        setError('Failed to load use cases. Please try again.');

        // Fallback to static templates if database fails
        try {
          const { USE_CASE_TEMPLATES } = await import('../../data/useCaseTemplates');
          const fallbackCases = USE_CASE_TEMPLATES.map((template: any) => ({
            ...template,
            id: template.id,
            created_at: new Date().toISOString(),
            updated_at: new Date().toISOString(),
            industry_standards: {},
            validation_sources: [],
            usage_count: 0,
            average_roi: null,
            average_payback_years: null,
            last_used: null,
            created_by: null,
            updated_by: null,
            image_url: template.image || null
          })) as UseCaseWithConfiguration[];

          setUseCases(fallbackCases);
          setFilteredCases(fallbackCases);
          setError('Using offline data. Some features may be limited.');
        } catch (fallbackErr) {
          setError('Failed to load use cases completely.');
        }
      } finally {
        setLoading(false);
      }
    };

    loadUseCases();
  }, [category, tier]);

  // Filter function for search/category changes
  const filterUseCases = (searchTerm: string, filterCategory?: string) => {
    let filtered = useCases;

    if (searchTerm) {
      const term = searchTerm.toLowerCase();
      filtered = filtered.filter(uc => 
        uc.name.toLowerCase().includes(term) || 
        uc.description?.toLowerCase().includes(term)
      );
    }

    if (filterCategory) {
      filtered = filtered.filter(uc => uc.category === filterCategory);
    }

    setFilteredCases(filtered);
  };

  // Handle use case selection with analytics
  const handleUseCaseSelect = async (useCase: UseCaseWithConfiguration) => {
    // Log analytics event
    await useCaseService.logAnalyticsEvent({
      use_case_id: useCase.id,
      event_type: 'selected',
      event_data: { component: 'UseCaseSelector' }
    });

    onUseCaseSelect?.(useCase);
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center p-8">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></div>
        <span className="ml-3 text-gray-600">Loading use cases...</span>
      </div>
    );
  }

  if (error) {
    return (
      <div className="bg-yellow-50 border border-yellow-200 rounded-md p-4">
        <div className="flex">
          <div className="flex-shrink-0">
            <svg className="h-5 w-5 text-yellow-400" viewBox="0 0 20 20" fill="currentColor">
              <path fillRule="evenodd" d="M8.257 3.099c.765-1.36 2.722-1.36 3.486 0l5.58 9.92c.75 1.334-.213 2.98-1.742 2.98H4.42c-1.53 0-2.493-1.646-1.743-2.98l5.58-9.92zM11 13a1 1 0 11-2 0 1 1 0 012 0zm-1-8a1 1 0 00-1 1v3a1 1 0 002 0V6a1 1 0 00-1-1z" clipRule="evenodd" />
            </svg>
          </div>
          <div className="ml-3">
            <p className="text-sm text-yellow-800">{error}</p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {/* Search and Filter */}
      <div className="flex flex-col sm:flex-row gap-4">
        <input
          type="text"
          placeholder="Search use cases..."
          className="flex-1 px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
          onChange={(e) => filterUseCases(e.target.value)}
        />
        <select
          className="px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
          onChange={(e) => filterUseCases('', e.target.value || undefined)}
        >
          <option value="">All Categories</option>
          <option value="commercial">Commercial</option>
          <option value="industrial">Industrial</option>
          <option value="institutional">Institutional</option>
          <option value="residential">Residential</option>
          <option value="agricultural">Agricultural</option>
        </select>
      </div>

      {/* Use Case Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredCases.map(useCase => (
          <div
            key={useCase.id}
            className="bg-white border border-gray-200 rounded-lg p-6 hover:shadow-md transition-shadow cursor-pointer"
            onClick={() => handleUseCaseSelect(useCase)}
          >
            <div className="flex items-center mb-3">
              <span className="text-2xl mr-3">{useCase.icon}</span>
              <h3 className="text-lg font-semibold text-gray-900">{useCase.name}</h3>
            </div>

            <p className="text-gray-600 text-sm mb-4">{useCase.description}</p>

            <div className="flex justify-between items-center text-xs text-gray-500">
              <span className="bg-gray-100 px-2 py-1 rounded">
                {useCase.category}
              </span>
              <span>
                {useCase.usage_count || 0} times used
              </span>
            </div>

            {useCase.default_configuration && (
              <div className="mt-3 text-xs text-gray-600">
                <div>Load: {useCase.default_configuration.typical_load_kw}kW</div>
                <div>Savings: {useCase.default_configuration.typical_savings_percent}%</div>
              </div>
            )}
          </div>
        ))}
      </div>

      {filteredCases.length === 0 && (
        <div className="text-center py-8 text-gray-500">
          No use cases found. Try adjusting your search or filters.
        </div>
      )}
    </div>
  );
};

// =================== SMART WIZARD INTEGRATION EXAMPLE ===================

interface SmartWizardProps {
  selectedUseCaseId?: string;
}

export const SmartWizardExample: React.FC<SmartWizardProps> = ({ selectedUseCaseId }) => {
  const [useCaseDetails, setUseCaseDetails] = useState<any>(null);
  const [configurations, setConfigurations] = useState<any[]>([]);
  const [customQuestions, setCustomQuestions] = useState<any[]>([]);
  const [userResponses, setUserResponses] = useState<Record<string, any>>({});
  const [calculation, setCalculation] = useState<any>(null);

  // Load detailed use case information
  useEffect(() => {
    const loadUseCaseDetails = async () => {
      if (!selectedUseCaseId) return;

      try {
        // Get use case by ID (you'd need to add this method to the service)
        const useCase = await useCaseService.getUseCaseBySlug(selectedUseCaseId);
        if (useCase) {
          setUseCaseDetails(useCase);
          setConfigurations(useCase.configurations);
          setCustomQuestions(useCase.custom_questions);
        }
      } catch (error) {
        console.error('Error loading use case details:', error);
      }
    };

    loadUseCaseDetails();
  }, [selectedUseCaseId]);

  // Calculate configuration based on user responses
  const handleCalculate = async () => {
    if (!useCaseDetails || configurations.length === 0) return;

    try {
      const defaultConfig = configurations.find(c => c.is_default) || configurations[0];
      const result = await useCaseService.calculateConfiguration(
        useCaseDetails.id,
        defaultConfig.id,
        userResponses
      );
      setCalculation(result);
    } catch (error) {
      console.error('Error calculating configuration:', error);
    }
  };

  // Render custom questions dynamically
  const renderCustomQuestions = () => {
    return customQuestions.map(question => {
      switch (question.question_type) {
        case 'number':
          return (
            <div key={question.id} className="mb-4">
              <label className="block text-sm font-medium text-gray-700 mb-1">
                {question.question_text}
                {question.is_required && <span className="text-red-500 ml-1">*</span>}
              </label>
              <input
                type="number"
                className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                defaultValue={question.default_value as number}
                min={question.min_value || undefined}
                max={question.max_value || undefined}
                step={question.step_value || 1}
                onChange={(e) => setUserResponses(prev => ({
                  ...prev,
                  [question.question_key]: parseFloat(e.target.value)
                }))}
              />
              {question.unit && (
                <span className="text-sm text-gray-500 ml-2">{question.unit}</span>
              )}
              {question.help_text && (
                <p className="text-xs text-gray-500 mt-1">{question.help_text}</p>
              )}
            </div>
          );

        case 'select':
          const options = question.select_options as any[] || [];
          return (
            <div key={question.id} className="mb-4">
              <label className="block text-sm font-medium text-gray-700 mb-1">
                {question.question_text}
                {question.is_required && <span className="text-red-500 ml-1">*</span>}
              </label>
              <select
                className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                defaultValue={question.default_value as string}
                onChange={(e) => setUserResponses(prev => ({
                  ...prev,
                  [question.question_key]: e.target.value
                }))}
              >
                {options.map(option => (
                  <option key={option.value} value={option.value}>
                    {option.label}
                  </option>
                ))}
              </select>
              {question.help_text && (
                <p className="text-xs text-gray-500 mt-1">{question.help_text}</p>
              )}
            </div>
          );

        case 'boolean':
          return (
            <div key={question.id} className="mb-4">
              <label className="flex items-center">
                <input
                  type="checkbox"
                  className="rounded border-gray-300 text-blue-600 shadow-sm focus:border-blue-300 focus:ring focus:ring-blue-200 focus:ring-opacity-50"
                  defaultChecked={question.default_value as boolean}
                  onChange={(e) => setUserResponses(prev => ({
                    ...prev,
                    [question.question_key]: e.target.checked
                  }))}
                />
                <span className="ml-2 text-sm text-gray-700">
                  {question.question_text}
                  {question.is_required && <span className="text-red-500 ml-1">*</span>}
                </span>
              </label>
              {question.help_text && (
                <p className="text-xs text-gray-500 mt-1 ml-6">{question.help_text}</p>
              )}
            </div>
          );

        default:
          return null;
      }
    });
  };

  if (!useCaseDetails) {
    return <div>Select a use case to begin configuration...</div>;
  }

  return (
    <div className="max-w-4xl mx-auto p-6">
      <h2 className="text-2xl font-bold mb-6">{useCaseDetails.name} Configuration</h2>

      {/* Custom Questions Form */}
      <div className="bg-white rounded-lg shadow p-6 mb-6">
        <h3 className="text-lg font-semibold mb-4">Configuration Questions</h3>
        {renderCustomQuestions()}

        <button
          onClick={handleCalculate}
          className="bg-blue-600 text-white px-6 py-2 rounded-md hover:bg-blue-700 transition-colors"
          disabled={!configurations.length}
        >
          Calculate System Requirements
        </button>
      </div>

      {/* Calculation Results */}
      {calculation && (
        <div className="bg-green-50 rounded-lg shadow p-6">
          <h3 className="text-lg font-semibold mb-4 text-green-800">System Recommendation</h3>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div>
              <p className="text-sm text-gray-600">Calculated Load</p>
              <p className="text-xl font-bold text-green-700">
                {calculation.calculated_load_kw.toFixed(1)} kW
              </p>
            </div>
            <div>
              <p className="text-sm text-gray-600">Recommended Size</p>
              <p className="text-xl font-bold text-green-700">
                {calculation.recommended_size_mw.toFixed(2)} MW
              </p>
            </div>
            <div>
              <p className="text-sm text-gray-600">Estimated Cost</p>
              <p className="text-xl font-bold text-green-700">
                ${calculation.estimated_cost.toLocaleString()}
              </p>
            </div>
            <div>
              <p className="text-sm text-gray-600">Annual Savings</p>
              <p className="text-xl font-bold text-green-700">
                ${calculation.projected_savings.toLocaleString()}
              </p>
            </div>
            <div>
              <p className="text-sm text-gray-600">Payback Period</p>
              <p className="text-xl font-bold text-green-700">
                {calculation.payback_years.toFixed(1)} years
              </p>
            </div>
            <div>
              <p className="text-sm text-gray-600">25-Year ROI</p>
              <p className="text-xl font-bold text-green-700">
                {calculation.roi_percentage.toFixed(1)}%
              </p>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default UseCaseSelector;

import React, { useState } from 'react';
import { X, ChevronRight, Check, Briefcase, Building2, Globe, DollarSign, Bell } from 'lucide-react';

interface AccountSetupProps {
  onClose: () => void;
  onComplete: (profileData: ProfileData) => void;
  onContinueToProfile: () => void; // New prop to navigate to enhanced profile
  userName: string;
  accountType: 'individual' | 'company';
  companyName?: string;
}

export type ProfileData = {
  jobTitle: string;
  companyName?: string;
  preferences: {
    defaultCurrency: string;
    defaultLocation: string;
    emailNotifications: boolean;
  };
};

export default function AccountSetup({ 
  onClose, 
  onComplete,
  onContinueToProfile,
  userName, 
  accountType,
  companyName 
}: AccountSetupProps) {
  const [step, setStep] = useState(1);
  const [profileData, setProfileData] = useState<ProfileData>({
    jobTitle: '',
    companyName: companyName || '',
    preferences: {
      defaultCurrency: 'USD',
      defaultLocation: 'US',
      emailNotifications: true,
    },
  });

  const totalSteps = 3;
  const handleNext = () => {
    if (step < totalSteps) {
      setStep(step + 1);
    } else {
      onComplete(profileData);
      // After saving basic profile, redirect to enhanced profile page
      onContinueToProfile();
    }
  };

  const handleSkip = () => {
    onComplete(profileData);
  };

  const isStepValid = () => {
    switch (step) {
      case 1:
        return profileData.jobTitle.trim().length > 0;
      case 2:
        return true; // Company info is optional for individuals
      case 3:
        return true; // Preferences have defaults
      default:
        return false;
    }
  };

  return (
    <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-2xl shadow-2xl max-w-2xl w-full relative animate-in fade-in zoom-in duration-300">
        {/* Close Button */}
        <button
          onClick={onClose}
          className="absolute right-4 top-4 text-gray-400 hover:text-gray-600 transition-colors z-10"
        >
          <X size={24} />
        </button>

        {/* Progress Bar */}
        <div className="px-8 pt-8">
          <div className="flex items-center justify-between mb-6">
            {[1, 2, 3].map((i) => (
              <React.Fragment key={i}>
                <div className="flex flex-col items-center flex-1">
                  <div
                    className={`w-10 h-10 rounded-full flex items-center justify-center font-bold transition-all ${
                      i < step
                        ? 'bg-green-500 text-white'
                        : i === step
                        ? 'bg-purple-600 text-white'
                        : 'bg-gray-200 text-gray-400'
                    }`}
                  >
                    {i < step ? <Check size={20} /> : i}
                  </div>
                  <div className="text-xs mt-2 font-medium text-gray-600">
                    {i === 1 && 'Profile'}
                    {i === 2 && 'Company'}
                    {i === 3 && 'Preferences'}
                  </div>
                </div>
                {i < 3 && (
                  <div
                    className={`h-1 flex-1 mx-2 mb-6 transition-all ${
                      i < step ? 'bg-green-500' : 'bg-gray-200'
                    }`}
                  />
                )}
              </React.Fragment>
            ))}
          </div>
        </div>

        {/* Content */}
        <div className="px-8 pb-8">
          <div className="mb-6">
            <h2 className="text-2xl font-bold text-gray-900 mb-2">
              {step === 1 && 'Tell us about yourself'}
              {step === 2 && 'Company information'}
              {step === 3 && 'Set your preferences'}
            </h2>
            <p className="text-gray-600">
              {step === 1 && 'Help us personalize your experience'}
              {step === 2 && 'Add details about your organization'}
              {step === 3 && 'Choose your default settings'}
            </p>
          </div>

          {/* Step 1: Job Title */}
          {step === 1 && (
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-bold text-gray-700 mb-2">
                  Job Title <span className="text-red-500">*</span>
                </label>
                <div className="relative">
                  <Briefcase className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" size={20} />
                  <input
                    type="text"
                    required
                    value={profileData.jobTitle}
                    onChange={(e) => setProfileData({ ...profileData, jobTitle: e.target.value })}
                    className="w-full border-2 border-gray-300 rounded-xl px-4 py-3 pl-11 focus:border-purple-400 focus:outline-none text-gray-900"
                    placeholder="e.g., Energy Consultant, Project Manager"
                  />
                </div>
              </div>
            </div>
          )}

          {/* Step 2: Company Info */}
          {step === 2 && (
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-bold text-gray-700 mb-2">
                  Company Name {accountType === 'company' && <span className="text-red-500">*</span>}
                </label>
                <div className="relative">
                  <Building2 className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" size={20} />
                  <input
                    type="text"
                    required={accountType === 'company'}
                    value={profileData.companyName}
                    onChange={(e) => setProfileData({ ...profileData, companyName: e.target.value })}
                    className="w-full border-2 border-gray-300 rounded-xl px-4 py-3 pl-11 focus:border-purple-400 focus:outline-none text-gray-900"
                    placeholder="Your company name"
                    disabled={accountType === 'company' && !!companyName}
                  />
                </div>
                {accountType === 'company' && companyName && (
                  <p className="text-xs text-gray-500 mt-2">
                    Set during signup. You can update this later in settings.
                  </p>
                )}
              </div>
            </div>
          )}

          {/* Step 3: Preferences */}
          {step === 3 && (
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-bold text-gray-700 mb-2">
                  Default Currency
                </label>
                <div className="relative">
                  <DollarSign className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" size={20} />
                  <select
                    value={profileData.preferences.defaultCurrency}
                    onChange={(e) =>
                      setProfileData({
                        ...profileData,
                        preferences: { ...profileData.preferences, defaultCurrency: e.target.value },
                      })
                    }
                    className="w-full border-2 border-gray-300 rounded-xl px-4 py-3 pl-11 focus:border-purple-400 focus:outline-none text-gray-900"
                  >
                    <option value="USD">USD - US Dollar</option>
                    <option value="EUR">EUR - Euro</option>
                    <option value="GBP">GBP - British Pound</option>
                    <option value="JPY">JPY - Japanese Yen</option>
                    <option value="CAD">CAD - Canadian Dollar</option>
                    <option value="AUD">AUD - Australian Dollar</option>
                  </select>
                </div>
              </div>

              <div>
                <label className="block text-sm font-bold text-gray-700 mb-2">
                  Default Location
                </label>
                <div className="relative">
                  <Globe className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" size={20} />
                  <select
                    value={profileData.preferences.defaultLocation}
                    onChange={(e) =>
                      setProfileData({
                        ...profileData,
                        preferences: { ...profileData.preferences, defaultLocation: e.target.value },
                      })
                    }
                    className="w-full border-2 border-gray-300 rounded-xl px-4 py-3 pl-11 focus:border-purple-400 focus:outline-none text-gray-900"
                  >
                    <option value="US">United States</option>
                    <option value="UK">United Kingdom</option>
                    <option value="EU">European Union</option>
                    <option value="CA">Canada</option>
                    <option value="AU">Australia</option>
                    <option value="JP">Japan</option>
                    <option value="CN">China</option>
                    <option value="IN">India</option>
                  </select>
                </div>
              </div>

              <div className="bg-gray-50 rounded-xl p-4">
                <label className="flex items-center cursor-pointer">
                  <input
                    type="checkbox"
                    checked={profileData.preferences.emailNotifications}
                    onChange={(e) =>
                      setProfileData({
                        ...profileData,
                        preferences: { ...profileData.preferences, emailNotifications: e.target.checked },
                      })
                    }
                    className="w-5 h-5 text-purple-600 rounded focus:ring-purple-500"
                  />
                  <div className="ml-3">
                    <div className="flex items-center">
                      <Bell size={16} className="text-gray-600 mr-2" />
                      <span className="font-bold text-gray-900">Email Notifications</span>
                    </div>
                    <p className="text-sm text-gray-600">
                      Receive updates about quotes, team activity, and new features
                    </p>
                  </div>
                </label>
              </div>
            </div>
          )}

          {/* Buttons */}
          <div className="flex items-center justify-between mt-8">
            <button
              onClick={handleSkip}
              className="text-gray-600 hover:text-gray-800 font-medium"
            >
              Skip for now
            </button>

            <div className="flex gap-3">
              {step > 1 && (
                <button
                  onClick={() => setStep(step - 1)}
                  className="px-6 py-3 rounded-xl border-2 border-gray-300 font-bold text-gray-700 hover:border-gray-400 transition-colors"
                >
                  Back
                </button>
              )}
              <button
                onClick={handleNext}
                disabled={!isStepValid()}
                className="px-6 py-3 rounded-xl bg-gradient-to-r from-purple-600 to-blue-600 text-white font-bold hover:shadow-lg transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2"
              >
                {step < totalSteps ? (
                  <>
                    Next <ChevronRight size={20} />
                  </>
                ) : (
                  <>
                    Complete <Check size={20} />
                  </>
                )}
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import { X, Send, Calendar, MessageSquare } from 'lucide-react';
import { supabase } from '../../services/supabaseClient';

interface ConsultationModalProps {
  isOpen: boolean;
  onClose: () => void;
  quoteData?: any;
}

const ConsultationModal: React.FC<ConsultationModalProps> = ({
  isOpen,
  onClose,
  quoteData
}) => {
  const [email, setEmail] = useState('');
  const [name, setName] = useState('');
  const [notes, setNotes] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [submitSuccess, setSubmitSuccess] = useState(false);
  const [errorMessage, setErrorMessage] = useState('');

  if (!isOpen) return null;

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    setErrorMessage('');

    try {
      // Save to Supabase customer_leads table
      const { data, error } = await supabase
        .from('customer_leads')
        .insert([
          {
            email,
            name,
            notes,
            quote_data: quoteData,
            created_at: new Date().toISOString(),
            lead_type: 'consultation_request'
          }
        ]);

      if (error) throw error;

      // Send email in background (mailto with pre-filled content)
      const subject = encodeURIComponent(`Consultation Request from ${name || email}`);
      const body = encodeURIComponent(
        `New consultation request:\n\n` +
        `Name: ${name || 'Not provided'}\n` +
        `Email: ${email}\n\n` +
        `Notes:\n${notes || 'No additional notes'}\n\n` +
        `Quote Data: ${quoteData ? JSON.stringify(quoteData, null, 2) : 'No quote data'}`
      );

      // Open mailto in hidden iframe to avoid navigation
      const iframe = document.createElement('iframe');
      iframe.style.display = 'none';
      iframe.src = `mailto:info@merlinenergy.com?subject=${subject}&body=${body}`;
      document.body.appendChild(iframe);
      setTimeout(() => document.body.removeChild(iframe), 1000);

      setSubmitSuccess(true);
      setTimeout(() => {
        onClose();
        setSubmitSuccess(false);
        setEmail('');
        setName('');
        setNotes('');
      }, 2000);

    } catch (error: any) {
      setErrorMessage(error.message || 'Failed to submit request. Please try again.');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-2xl max-w-2xl w-full max-h-[90vh] overflow-y-auto shadow-2xl">
        {/* Header */}
        <div className="sticky top-0 bg-gradient-to-r from-blue-600 to-indigo-600 text-white p-6 rounded-t-2xl flex items-center justify-between">
          <div className="flex items-center space-x-3">
            <Calendar className="w-8 h-8" />
            <div>
              <h2 className="text-2xl font-bold">Schedule Free Consultation</h2>
              <p className="text-blue-100 text-sm">We'll review your quote and get in touch</p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="p-2 hover:bg-white/20 rounded-lg transition-colors"
          >
            <X className="w-6 h-6" />
          </button>
        </div>

        {/* Content */}
        <div className="p-6 space-y-6">
          {submitSuccess ? (
            <div className="text-center py-12">
              <div className="text-6xl mb-4">✅</div>
              <h3 className="text-2xl font-bold text-green-600 mb-2">Request Submitted!</h3>
              <p className="text-gray-600">
                We've received your consultation request and will contact you shortly.
              </p>
            </div>
          ) : (
            <>
              {/* Info Section */}
              <div className="bg-blue-50 border-2 border-blue-200 rounded-xl p-4">
                <h3 className="font-bold text-blue-900 mb-2 flex items-center space-x-2">
                  <MessageSquare className="w-5 h-5" />
                  <span>What happens next?</span>
                </h3>
                <ul className="text-sm text-blue-800 space-y-1">
                  <li>✓ We'll receive your request immediately</li>
                  <li>✓ Our team will review your quote details</li>
                  <li>✓ We'll reach out within 24 hours to schedule a consultation</li>
                  <li>✓ Discuss options, pricing, and next steps</li>
                </ul>
              </div>

              {/* Form */}
              <form onSubmit={handleSubmit} className="space-y-4">
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-2">
                    Your Name *
                  </label>
                  <input
                    type="text"
                    value={name}
                    onChange={(e) => setName(e.target.value)}
                    required
                    className="w-full px-4 py-3 border-2 border-gray-300 rounded-lg focus:border-blue-500 focus:ring-2 focus:ring-blue-200 transition-colors"
                    placeholder="John Smith"
                  />
                </div>

                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-2">
                    Email Address *
                  </label>
                  <input
                    type="email"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    required
                    className="w-full px-4 py-3 border-2 border-gray-300 rounded-lg focus:border-blue-500 focus:ring-2 focus:ring-blue-200 transition-colors"
                    placeholder="john@company.com"
                  />
                </div>

                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-2">
                    Additional Notes (Optional)
                  </label>
                  <textarea
                    value={notes}
                    onChange={(e) => setNotes(e.target.value)}
                    rows={4}
                    className="w-full px-4 py-3 border-2 border-gray-300 rounded-lg focus:border-blue-500 focus:ring-2 focus:ring-blue-200 transition-colors resize-none"
                    placeholder="Tell us about your project timeline, specific requirements, or any questions you have..."
                  />
                </div>

                {errorMessage && (
                  <div className="bg-red-50 border-2 border-red-200 rounded-lg p-4 text-red-700">
                    {errorMessage}
                  </div>
                )}

                {/* Quote Summary */}
                {quoteData && (
                  <div className="bg-gray-50 border-2 border-gray-200 rounded-lg p-4">
                    <h4 className="font-semibold text-gray-900 mb-2">Your Quote Summary</h4>
                    <div className="text-sm text-gray-600 space-y-1">
                      {quoteData.capacity && (
                        <div>Capacity: <span className="font-semibold">{quoteData.capacity} kWh</span></div>
                      )}
                      {quoteData.power && (
                        <div>Power: <span className="font-semibold">{quoteData.power} kW</span></div>
                      )}
                      {quoteData.totalCost && (
                        <div>Estimated Cost: <span className="font-semibold">${quoteData.totalCost.toLocaleString()}</span></div>
                      )}
                    </div>
                  </div>
                )}

                {/* Submit Button */}
                <div className="flex space-x-3 pt-4">
                  <button
                    type="button"
                    onClick={onClose}
                    className="flex-1 px-6 py-3 bg-gray-200 text-gray-700 rounded-lg font-semibold hover:bg-gray-300 transition-colors"
                  >
                    Cancel
                  </button>
                  <button
                    type="submit"
                    disabled={isSubmitting}
                    className="flex-1 px-6 py-3 bg-gradient-to-r from-blue-600 to-indigo-600 text-white rounded-lg font-semibold hover:from-blue-700 hover:to-indigo-700 transition-colors disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center space-x-2"
                  >
                    {isSubmitting ? (
                      <>
                        <div className="animate-spin rounded-full h-5 w-5 border-b-2 border-white"></div>
                        <span>Submitting...</span>
                      </>
                    ) : (
                      <>
                        <Send className="w-5 h-5" />
                        <span>Submit Request</span>
                      </>
                    )}
                  </button>
                </div>
              </form>
            </>
          )}
        </div>
      </div>
    </div>
  );
};

export default ConsultationModal;

/**
 * Download Gate Modal
 * Smart modal that:
 * - Checks if user is logged in → proceeds directly to download
 * - If not logged in → shows sign-up form first
 * Replaces the separate EmailCaptureModal with auth-aware behavior
 */

import React, { useState, useEffect } from 'react';
import { X, Mail, User, Building2, CheckCircle, AlertCircle, Download, UserCheck, Sparkles } from 'lucide-react';
import { supabase } from '../../services/supabaseClient';
import { authService } from '../../services/authService';

type DownloadType = 'pdf' | 'excel' | 'word' | 'certificate';

interface DownloadGateModalProps {
  isOpen: boolean;
  onClose: () => void;
  onProceedWithDownload: () => void;
  onShowLogin?: () => void;
  downloadType: DownloadType;
  quoteData?: {
    storageSizeMW?: number;
    totalCost?: number;
    industryName?: string;
  };
}

const DOWNLOAD_LABELS: Record<DownloadType, { icon: string; label: string; color: string }> = {
  pdf: { icon: '📄', label: 'PDF Quote', color: 'from-red-500 to-red-600' },
  excel: { icon: '📊', label: 'Excel Quote', color: 'from-green-500 to-green-600' },
  word: { icon: '📝', label: 'Word Quote', color: 'from-blue-500 to-blue-600' },
  certificate: { icon: '🏆', label: 'Power Certificate', color: 'from-purple-500 to-indigo-600' },
};

const DownloadGateModal: React.FC<DownloadGateModalProps> = ({
  isOpen,
  onClose,
  onProceedWithDownload,
  onShowLogin,
  downloadType,
  quoteData
}) => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [isCheckingAuth, setIsCheckingAuth] = useState(true);
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    company: '',
  });
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState(false);

  // Check auth status when modal opens
  useEffect(() => {
    if (isOpen) {
      checkAuthStatus();
    }
  }, [isOpen]);

  const checkAuthStatus = async () => {
    setIsCheckingAuth(true);
    try {
      // Check both authService (local) and Supabase
      const localUser = authService.getCurrentUser();
      const { data: { user: supabaseUser } } = await supabase.auth.getUser();

      if (localUser || supabaseUser) {
        setIsLoggedIn(true);
        // Auto-proceed with download after a brief moment
        setTimeout(() => {
          onProceedWithDownload();
          onClose();
        }, 500);
      } else {
        setIsLoggedIn(false);
      }
    } catch (err) {
      console.error('Auth check error:', err);
      setIsLoggedIn(false);
    } finally {
      setIsCheckingAuth(false);
    }
  };

  if (!isOpen) return null;

  const downloadInfo = DOWNLOAD_LABELS[downloadType];

  const handleInputChange = (field: string, value: string) => {
    setFormData(prev => ({ ...prev, [field]: value }));
    setError(null);
  };

  const validateEmail = (email: string): boolean => {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(email);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    // Validation
    if (!formData.name.trim()) {
      setError('Please enter your name');
      return;
    }
    if (!formData.email.trim()) {
      setError('Please enter your email');
      return;
    }
    if (!validateEmail(formData.email)) {
      setError('Please enter a valid email address');
      return;
    }
    if (!formData.company.trim()) {
      setError('Please enter your company name');
      return;
    }

    setIsLoading(true);
    setError(null);

    try {
      // Generate a temporary password
      const tempPassword = Math.random().toString(36).slice(-12) + 'A1!';

      // Try to sign up with Supabase Auth
      const { data: authData, error: signUpError } = await supabase.auth.signUp({
        email: formData.email,
        password: tempPassword,
        options: {
          data: {
            full_name: formData.name,
            company: formData.company,
          },
        },
      });

      if (signUpError) {
        // If user already exists, that's fine - we'll proceed anyway
        if (!signUpError.message.includes('already registered')) {
          console.error('Sign up error:', signUpError);
        }
      }

      // Also save to local authService for immediate access
      const userId = authData?.user?.id || `local_${Date.now()}`;

      // Save lead info to localStorage (backup)
      const leads = JSON.parse(localStorage.getItem('merlin_download_leads') || '[]');
      leads.push({
        ...formData,
        userId,
        downloadType,
        quoteData,
        timestamp: new Date().toISOString(),
      });
      localStorage.setItem('merlin_download_leads', JSON.stringify(leads));

      // Try to save to Supabase (non-blocking)
      try {
        await supabase.from('download_leads').insert({
          name: formData.name,
          email: formData.email,
          company: formData.company,
          download_type: downloadType,
          quote_data: quoteData,
          created_at: new Date().toISOString(),
        });
      } catch (dbErr) {
        // Table might not exist - that's OK
        if (import.meta.env.DEV) { console.log('Lead table insert (may not exist):', dbErr); }
      }

      setSuccess(true);

      // Wait for success animation then proceed with download
      setTimeout(() => {
        onProceedWithDownload();
        onClose();
        // Reset form
        setFormData({ name: '', email: '', company: '' });
        setSuccess(false);
      }, 1500);

    } catch (err: any) {
      console.error('Sign up error:', err);
      setError(err.message || 'Failed to create account. Please try again.');
      setIsLoading(false);
    }
  };

  // Loading state while checking auth
  if (isCheckingAuth) {
    return (
      <div className="fixed inset-0 z-50 overflow-y-auto">
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm transition-opacity" />
        <div className="flex min-h-full items-center justify-center p-4">
          <div className="bg-white rounded-2xl p-8 text-center">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-purple-600 mx-auto mb-4"></div>
            <p className="text-gray-600">Checking your account...</p>
          </div>
        </div>
      </div>
    );
  }

  // If logged in, show quick success (this usually auto-closes)
  if (isLoggedIn && !success) {
    return (
      <div className="fixed inset-0 z-50 overflow-y-auto">
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm transition-opacity" />
        <div className="flex min-h-full items-center justify-center p-4">
          <div className="bg-white rounded-2xl p-8 text-center max-w-sm">
            <div className="mx-auto w-16 h-16 bg-green-100 rounded-full flex items-center justify-center mb-4">
              <UserCheck className="w-10 h-10 text-green-600" />
            </div>
            <h3 className="text-xl font-bold text-gray-900 mb-2">Welcome Back!</h3>
            <p className="text-gray-600">Starting your download...</p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="fixed inset-0 z-50 overflow-y-auto">
      {/* Backdrop */}
      <div 
        className="fixed inset-0 bg-black/60 backdrop-blur-sm transition-opacity"
        onClick={onClose}
      />

      {/* Modal */}
      <div className="flex min-h-full items-center justify-center p-4">
        <div className="relative bg-white rounded-3xl shadow-2xl max-w-md w-full overflow-hidden">
          {/* Header */}
          <div className={`bg-gradient-to-r ${downloadInfo.color} px-6 py-5 relative overflow-hidden`}>
            {/* Decorative elements */}
            <div className="absolute top-0 right-0 w-32 h-32 bg-white/10 rounded-full -translate-y-1/2 translate-x-1/2"></div>

            <div className="relative z-10 flex justify-between items-start">
              <div className="flex items-center gap-3">
                <div className="text-4xl">{downloadInfo.icon}</div>
                <div>
                  <h2 className="text-xl font-bold text-white">Download {downloadInfo.label}</h2>
                  <p className="text-white/80 text-sm mt-0.5">
                    Create a free account to continue
                  </p>
                </div>
              </div>
              <button
                onClick={onClose}
                className="text-white/80 hover:text-white hover:bg-white/20 rounded-lg p-2 transition-colors"
                disabled={isLoading}
              >
                <X className="w-5 h-5" />
              </button>
            </div>
          </div>

          {/* Content */}
          <div className="p-6">
            {success ? (
              // Success State
              <div className="text-center py-6 space-y-4">
                <div className="mx-auto w-16 h-16 bg-gradient-to-r from-green-400 to-emerald-500 rounded-full flex items-center justify-center shadow-lg">
                  <CheckCircle className="w-10 h-10 text-white" />
                </div>
                <h3 className="text-xl font-bold text-gray-900">Success! 🎉</h3>
                <p className="text-gray-600">
                  Your download is starting...
                </p>
              </div>
            ) : (
              // Sign Up Form
              <form onSubmit={handleSubmit} className="space-y-4">
                {/* Benefits banner */}
                <div className="bg-gradient-to-r from-purple-50 to-indigo-50 rounded-xl p-3 border border-purple-100 mb-4">
                  <div className="flex items-center gap-2 text-sm text-purple-700">
                    <Sparkles className="w-4 h-4 text-purple-500" />
                    <span className="font-medium">Free account includes:</span>
                    <span>saved quotes • portfolio • price alerts</span>
                  </div>
                </div>

                {/* Name Input */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1.5">
                    Full Name *
                  </label>
                  <div className="relative">
                    <User className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                    <input
                      type="text"
                      value={formData.name}
                      onChange={(e) => handleInputChange('name', e.target.value)}
                      placeholder="John Smith"
                      disabled={isLoading}
                      className="w-full pl-10 pr-4 py-3 border-2 border-gray-200 rounded-xl focus:ring-2 focus:ring-purple-500 focus:border-purple-500 transition-all disabled:bg-gray-100 disabled:cursor-not-allowed"
                      required
                    />
                  </div>
                </div>

                {/* Email Input */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1.5">
                    Email Address *
                  </label>
                  <div className="relative">
                    <Mail className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                    <input
                      type="email"
                      value={formData.email}
                      onChange={(e) => handleInputChange('email', e.target.value)}
                      placeholder="john@company.com"
                      disabled={isLoading}
                      className="w-full pl-10 pr-4 py-3 border-2 border-gray-200 rounded-xl focus:ring-2 focus:ring-purple-500 focus:border-purple-500 transition-all disabled:bg-gray-100 disabled:cursor-not-allowed"
                      required
                    />
                  </div>
                </div>

                {/* Company Input */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1.5">
                    Company Name *
                  </label>
                  <div className="relative">
                    <Building2 className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                    <input
                      type="text"
                      value={formData.company}
                      onChange={(e) => handleInputChange('company', e.target.value)}
                      placeholder="Acme Corp"
                      disabled={isLoading}
                      className="w-full pl-10 pr-4 py-3 border-2 border-gray-200 rounded-xl focus:ring-2 focus:ring-purple-500 focus:border-purple-500 transition-all disabled:bg-gray-100 disabled:cursor-not-allowed"
                      required
                    />
                  </div>
                </div>

                {/* Error Message */}
                {error && (
                  <div className="p-3 bg-red-50 border-2 border-red-200 rounded-xl flex items-start gap-3">
                    <AlertCircle className="w-5 h-5 text-red-600 flex-shrink-0 mt-0.5" />
                    <p className="text-sm text-red-700">{error}</p>
                  </div>
                )}

                {/* Privacy Notice */}
                <p className="text-xs text-gray-500 text-center">
                  By signing up, you agree to receive occasional updates about battery storage solutions.
                </p>

                {/* Submit Button */}
                <button
                  type="submit"
                  disabled={isLoading}
                  className={`w-full py-3.5 bg-gradient-to-r ${downloadInfo.color} text-white font-bold rounded-xl hover:opacity-90 transition-all shadow-lg hover:shadow-xl disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2`}
                >
                  {isLoading ? (
                    <>
                      <div className="animate-spin rounded-full h-5 w-5 border-b-2 border-white" />
                      Creating Account...
                    </>
                  ) : (
                    <>
                      <Download className="w-5 h-5" />
                      Sign Up & Download
                    </>
                  )}
                </button>
              </form>
            )}
          </div>

          {/* Footer */}
          {!success && (
            <div className="border-t border-gray-100 px-6 py-3 bg-gray-50">
              <p className="text-xs text-center text-gray-500">
                Already have an account? <a href="#" className="text-purple-600 font-medium hover:underline" onClick={(e) => { e.preventDefault(); onClose(); onShowLogin?.(); }}>Sign in</a> for instant access.
              </p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default DownloadGateModal;

/**
