// ============================================
// HELPER: Generate BESS Breakdown Data
// ============================================

export function generateBESSBreakdown(
  powerKW: number,
  capacityKWh: number,
  durationHours: number,
  pricingTier: 'residential' | 'commercial' | 'utility'
): ComponentBreakdown {
  // Tier-based pricing (Dec 2025 benchmarks)
  const batteryPricePerKWh = {
    residential: 350,
    commercial: 175,
    utility: 140,
  }[pricingTier];

  const pcsPerKW = {
    residential: 200,
    commercial: 120,
    utility: 100,
  }[pricingTier];

  const batteryCost = capacityKWh * batteryPricePerKWh;
  const pcsCost = powerKW * pcsPerKW;
  const subtotal = batteryCost + pcsCost;

  return {
    name: 'Battery Energy Storage System (BESS)',
    icon: Battery,
    assumptions: [
      { item: 'Battery Price', value: batteryPricePerKWh, unit: '$/kWh', source: 'NREL ATB 2024 + Market', tier: pricingTier },
      { item: 'PCS/Inverter Price', value: pcsPerKW, unit: '$/kW', source: 'Professional Quotes Oct 2025', tier: pricingTier },
      { item: 'System Power', value: powerKW, unit: 'kW', source: 'User Input', tier: pricingTier },
      { item: 'Energy Capacity', value: capacityKWh, unit: 'kWh', source: 'Calculated', tier: pricingTier },
      { item: 'Duration', value: durationHours, unit: 'hours', source: 'User Input', tier: pricingTier },
    ],
    calculations: [
      {
        description: 'Calculate battery module cost',
        formula: 'Battery Cost = Capacity (kWh) × Price per kWh',
        inputs: [
          { name: 'Capacity', value: capacityKWh, unit: 'kWh' },
          { name: 'Price', value: batteryPricePerKWh, unit: '$/kWh' },
        ],
        result: batteryCost,
        resultUnit: '$',
      },
      {
        description: 'Calculate PCS/inverter cost',
        formula: 'PCS Cost = Power (kW) × Price per kW',
        inputs: [
          { name: 'Power', value: powerKW, unit: 'kW' },
          { name: 'Price', value: pcsPerKW, unit: '$/kW' },
        ],
        result: pcsCost,
        resultUnit: '$',
      },
      {
        description: 'Sum BESS component costs',
        formula: 'BESS Total = Battery Cost + PCS Cost',
        inputs: [
          { name: 'Battery', value: batteryCost, unit: '$' },
          { name: 'PCS', value: pcsCost, unit: '$' },
        ],
        result: subtotal,
        resultUnit: '$',
      },
    ],
    subtotal,
  };
}

// ============================================
// HELPER: Generate Solar Breakdown Data
// ============================================

export function generateSolarBreakdown(
  systemSizeKW: number,
  pricingTier: 'residential' | 'commercial' | 'utility'
): ComponentBreakdown {
  // Tier-based pricing (Dec 2025 benchmarks)
  const pricePerWatt = {
    residential: 2.80,
    commercial: 1.05,
    utility: 0.65,
  }[pricingTier];

  const totalCost = systemSizeKW * 1000 * pricePerWatt;

  return {
    name: 'Solar PV Array',
    icon: Sun,
    assumptions: [
      { item: 'System Price', value: pricePerWatt, unit: '$/W', source: 'NREL + Professional Quotes', tier: pricingTier },
      { item: 'System Size', value: systemSizeKW, unit: 'kW', source: 'User Selection', tier: pricingTier },
      { item: 'Panel Efficiency', value: 21.5, unit: '%', source: 'Tier-1 Mono-PERC', tier: pricingTier },
    ],
    calculations: [
      {
        description: 'Calculate turnkey solar system cost',
        formula: 'Solar Cost = System Size (kW) × 1000 × Price per Watt',
        inputs: [
          { name: 'System Size', value: systemSizeKW, unit: 'kW' },
          { name: 'Price', value: pricePerWatt, unit: '$/W' },
        ],
        result: totalCost,
        resultUnit: '$',
      },
    ],
    subtotal: totalCost,
  };
}

/**
 * RequestQuoteModal.tsx
 * Professional quote request form - replaces mailto: links
 * Captures lead info: name, company, email, phone, message
 */

import React, { useState } from "react";
import {
  X,
  Mail,
  User,
  Building2,
  Phone,
  MessageSquare,
  CheckCircle,
  AlertCircle,
  Sparkles,
  Send,
  Shield,
} from "lucide-react";
import { supabase } from "../../services/supabaseClient";

interface RequestQuoteModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSuccess?: () => void;
  quoteData?: {
    storageSizeMW?: number;
    durationHours?: number;
    energyCapacity?: number;
    solarMW?: number;
    totalCost?: number;
    industryName?: string;
    location?: string;
  };
}

const RequestQuoteModal: React.FC<RequestQuoteModalProps> = ({
  isOpen,
  onClose,
  onSuccess,
  quoteData,
}) => {
  const [formData, setFormData] = useState({
    firstName: "",
    lastName: "",
    email: "",
    company: "",
    phone: "",
    message: "",
  });
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState(false);

  if (!isOpen) return null;

  const handleInputChange = (field: string, value: string) => {
    setFormData((prev) => ({ ...prev, [field]: value }));
    setError(null);
  };

  const validateEmail = (email: string): boolean => {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(email);
  };

  const validatePhone = (phone: string): boolean => {
    const phoneRegex = /^[\d\s\-\+\(\)\.]{10,}$/;
    return phone.length === 0 || phoneRegex.test(phone);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!formData.firstName.trim()) return setError("Please enter your first name");
    if (!formData.lastName.trim()) return setError("Please enter your last name");
    if (!formData.email.trim()) return setError("Please enter your email");
    if (!validateEmail(formData.email)) return setError("Please enter a valid email address");
    if (!formData.company.trim()) return setError("Please enter your company name");
    if (formData.phone && !validatePhone(formData.phone))
      return setError("Please enter a valid phone number");

    setIsLoading(true);
    setError(null);

    try {
      const { error: insertError } = await supabase.from("quote_requests").insert({
        first_name: formData.firstName.trim(),
        last_name: formData.lastName.trim(),
        email: formData.email.trim().toLowerCase(),
        company: formData.company.trim(),
        phone: formData.phone.trim() || null,
        message: formData.message.trim() || null,
        quote_data: quoteData || null,
        status: "new",
        created_at: new Date().toISOString(),
      });

      if (insertError) {
        if (import.meta.env.DEV) {
          console.log("Quote request (table may not exist):", insertError);
        }

        const existingRequests = JSON.parse(
          localStorage.getItem("merlin_quote_requests") || "[]"
        );
        existingRequests.push({
          ...formData,
          quoteData,
          timestamp: new Date().toISOString(),
        });
        localStorage.setItem("merlin_quote_requests", JSON.stringify(existingRequests));
      }

      setSuccess(true);

      setTimeout(() => {
        onSuccess?.();
        onClose();
        setFormData({
          firstName: "",
          lastName: "",
          email: "",
          company: "",
          phone: "",
          message: "",
        });
        setSuccess(false);
        setIsLoading(false);
      }, 2500);
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : "Failed to submit request. Please try again.";
      console.error("Quote request error:", err);
      setError(message);
      setIsLoading(false);
    }
  };

  const formatSystemSummary = () => {
    if (!quoteData) return null;

    const parts: string[] = [];
    if (quoteData.storageSizeMW) parts.push(`${quoteData.storageSizeMW.toFixed(2)} MW`);
    if (quoteData.durationHours) parts.push(`${quoteData.durationHours}h duration`);
    if (quoteData.energyCapacity) parts.push(`${quoteData.energyCapacity.toFixed(1)} MWh`);
    if (quoteData.solarMW) parts.push(`+ ${quoteData.solarMW.toFixed(1)} MW Solar`);

    return parts.join(" • ");
  };

  return (
    <div className="fixed inset-0 z-50 overflow-y-auto">
      <div
        className="fixed inset-0 bg-black/60 backdrop-blur-sm transition-opacity"
        onClick={onClose}
      />

      <div className="flex min-h-full items-center justify-center p-4">
        <div className="relative bg-white rounded-3xl shadow-2xl max-w-lg w-full overflow-hidden">
          <div className="bg-gradient-to-r from-purple-700 via-indigo-600 to-purple-800 px-6 py-6 relative overflow-hidden">
            <div className="absolute top-0 right-0 w-32 h-32 bg-white/10 rounded-full -translate-y-1/2 translate-x-1/2"></div>
            <div className="absolute bottom-0 left-0 w-24 h-24 bg-white/10 rounded-full translate-y-1/2 -translate-x-1/2"></div>

            <div className="relative z-10 flex justify-between items-start">
              <div className="flex items-center gap-4">
                <div className="text-5xl">🧙‍♂️</div>
                <div>
                  <h2 className="text-2xl font-bold text-white">Request Official Quote</h2>
                  <p className="text-purple-200 text-sm mt-1">
                    Our energy experts will contact you within 24 hours
                  </p>
                </div>
              </div>
              <button
                onClick={onClose}
                className="text-white/80 hover:text-white hover:bg-white/20 rounded-lg p-2 transition-colors"
                disabled={isLoading}
              >
                <X className="w-6 h-6" />
              </button>
            </div>

            {formatSystemSummary() && (
              <div className="mt-4 inline-flex items-center gap-2 px-3 py-1.5 bg-white/20 rounded-full text-white text-sm">
                <Sparkles className="w-4 h-4" />
                <span>{formatSystemSummary()}</span>
              </div>
            )}
          </div>

          <div className="p-6">
            {success ? (
              <div className="text-center py-8 space-y-4">
                <div className="mx-auto w-20 h-20 bg-gradient-to-r from-green-400 to-emerald-500 rounded-full flex items-center justify-center shadow-lg">
                  <CheckCircle className="w-12 h-12 text-white" />
                </div>
                <h3 className="text-2xl font-bold text-gray-900">Request Submitted! 🎉</h3>
                <p className="text-gray-600 max-w-sm mx-auto">
                  Thank you, <strong>{formData.firstName}</strong>! Our team will reach out to you
                  at <strong>{formData.email}</strong> within 24 hours.
                </p>
                <div className="flex items-center justify-center gap-2 text-sm text-purple-600 mt-4">
                  <Shield className="w-4 h-4" />
                  <span>Your information is safe with us</span>
                </div>
              </div>
            ) : (
              <form onSubmit={handleSubmit} className="space-y-4">
                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1.5">
                      First Name *
                    </label>
                    <div className="relative">
                      <User className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                      <input
                        type="text"
                        value={formData.firstName}
                        onChange={(e) => handleInputChange("firstName", e.target.value)}
                        placeholder="John"
                        disabled={isLoading}
                        className="w-full pl-10 pr-4 py-3 border-2 border-gray-200 rounded-xl focus:ring-2 focus:ring-purple-500 focus:border-purple-500 transition-all disabled:bg-gray-100 disabled:cursor-not-allowed"
                        required
                      />
                    </div>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1.5">
                      Last Name *
                    </label>
                    <input
                      type="text"
                      value={formData.lastName}
                      onChange={(e) => handleInputChange("lastName", e.target.value)}
                      placeholder="Smith"
                      disabled={isLoading}
                      className="w-full px-4 py-3 border-2 border-gray-200 rounded-xl focus:ring-2 focus:ring-purple-500 focus:border-purple-500 transition-all disabled:bg-gray-100 disabled:cursor-not-allowed"
                      required
                    />
                  </div>
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1.5">
                    Company Name *
                  </label>
                  <div className="relative">
                    <Building2 className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                    <input
                      type="text"
