            </div>
            <div className="flex-1">
              <p className="text-white text-lg">
                <span className="font-bold text-amber-300">{state.businessName}</span>, let&apos;s configure your hotel&apos;s energy system!
              </p>
              <p className="text-slate-300 text-sm">
