          {/* Title Overlay */}
          <div style={{
            position: 'absolute',
            bottom: 0,
            left: 0,
            right: 0,
            padding: '24px 32px',
            textAlign: 'center'
          }}>
            <h1 style={{ 
              fontSize: 36, 
              fontWeight: 700, 
              margin: 0,
              color: COLORS.value,
              textShadow: '0 2px 8px rgba(0,0,0,0.5)'
