          </div>

          {/* HVAC */}
          <div style={{ marginTop: 24 }}>
            <label style={{ fontSize: 14, color: COLORS.label, textTransform: 'uppercase', letterSpacing: 1, marginBottom: 12, display: 'block' }}>
