export function getSizeOptionsForIndustry(industrySlug: string): BusinessSizeOption[] {
  const normalized = industrySlug.replace(/-/g, '_');
  return INDUSTRY_SIZE_OPTIONS[normalized] || DEFAULT_SIZE_OPTIONS;
}

