              {/* Gradient overlay */}
              <div
                className={`absolute inset-0 bg-gradient-to-t from-black/90 via-black/40 to-transparent transition-opacity ${
                  isSelected ? "opacity-95" : "opacity-80 group-hover:opacity-90"
