const CLIMATE_GOAL_MAP: Record<string, EnergyGoal[]> = {
  extreme_heat: ["reduce_costs", "peak_shaving"],
  hurricane: ["backup_power", "grid_independence"],
  extreme_cold: ["backup_power", "reduce_costs"],
