                </div>
                <div>
                  <div className="text-xs text-slate-500 uppercase tracking-wide">Climate Signal</div>
                  {enrichedData.weather.extremes ? (
                    <div className="text-white font-semibold text-sm mt-0.5">
                      {enrichedData.weather.extremes}
