  updateQuote: (updates: QuoteDocumentUpdate, source?: "user" | "ai" | "system") => void;

  // Actions
  resetQuote: () => void;
  loadQuote: (quote: QuoteDocument) => void;

  // Computed values
  completionPercentage: number;
