/**
 * Generate human-readable reasoning for suggestion
 */
function generateReasoning(
  current: AIOptimizationInput,
  baseline: any,
  currentMetrics: any,
  baselineMetrics: any,
  roiDiff: number
): string {
  const isOversized = current.storageSizeMW > baseline.powerMW;
  const isUndersized = current.storageSizeMW < baseline.powerMW;
  const sizeDiff = Math.abs(current.storageSizeMW - baseline.powerMW);

  if (isOversized && roiDiff > 0.5) {
    return `Your ${current.storageSizeMW}MW configuration is oversized for this use case. Reducing to ${baseline.powerMW}MW would save $${(Math.abs(currentMetrics.netCost - baselineMetrics.netCost) / 1000000).toFixed(1)}M in upfront cost while maintaining similar revenue, improving payback by ${Math.abs(roiDiff).toFixed(1)} years.`;
  }

  if (isUndersized) {
    return `Your ${current.storageSizeMW}MW configuration may be undersized. Increasing to ${baseline.powerMW}MW would add $${((currentMetrics.netCost - baselineMetrics.netCost) / 1000000).toFixed(1)}M cost but generate $${((baselineMetrics.annualSavings - currentMetrics.annualSavings) / 1000).toFixed(0)}K more annual revenue, improving overall ROI.`;
  }

  if (current.durationHours !== baseline.durationHrs) {
    return `Adjusting duration from ${current.durationHours}hr to ${baseline.durationHrs}hr would better match industry standards for ${current.useCase}, optimizing the power-to-energy ratio for maximum efficiency.`;
  }

  return `The ${baseline.powerMW}MW / ${baseline.durationHrs}hr configuration is optimized based on ${current.useCase} industry benchmarks, providing the best balance of cost, revenue, and ROI.`;
}

/**
 * Format cost impact as readable string
 */
function formatCostImpact(costDiff: number): string {
  const absDiff = Math.abs(costDiff);
  const millions = (absDiff / 1000000).toFixed(1);

  if (costDiff > 0) {
    return `Adds $${millions}M to project cost`;
  } else if (costDiff < 0) {
    return `Saves $${millions}M in project cost`;
  } else {
    return "Similar project cost";
  }
}

/**
 * Format ROI impact as readable string
 */
function formatROIImpact(roiDiff: number): string {
  const absDiff = Math.abs(roiDiff).toFixed(1);

  if (roiDiff > 0.3) {
    return `Improves payback by ${absDiff} years`;
  } else if (roiDiff < -0.3) {
    return `Extends payback by ${absDiff} years`;
  } else {
    return "Similar payback period";
  }
}

/**
 * Determine confidence level in suggestion
 */
function determineConfidence(sizeDiffPercent: number, roiDiff: number): "high" | "medium" | "low" {
  if (sizeDiffPercent > 50 || Math.abs(roiDiff) > 2) {
    return "high"; // Large differences = high confidence suggestion is beneficial
  } else if (sizeDiffPercent > 25 || Math.abs(roiDiff) > 1) {
    return "medium";
  } else {
    return "low";
  }
}

/**
 * Calculate percentile ranking compared to industry benchmarks
 */
function calculateBenchmarkPercentile(
  metrics: any,
  useCase: string
): { percentile: number; comparison: string } {
  // Simplified percentile calculation based on ROI
  // In production, this would compare against historical data
  const roi10Year = metrics.roi10Year;
  const paybackYears = metrics.paybackYears;

  let percentile = 50; // Default to median

  // Excellent performance
  if (roi10Year > 150 && paybackYears < 4) {
    percentile = 90;
  } else if (roi10Year > 120 && paybackYears < 5) {
    percentile = 75;
  } else if (roi10Year > 100 && paybackYears < 6) {
    percentile = 60;
  } else if (roi10Year < 80 || paybackYears > 7) {
    percentile = 30;
  }

  let comparison = "";
  if (percentile >= 80) {
    comparison = `Top ${100 - percentile}% for ${useCase} installations`;
  } else if (percentile >= 60) {
    comparison = `Above average for ${useCase} installations`;
  } else if (percentile >= 40) {
    comparison = `Average performance for ${useCase} installations`;
  } else {
    comparison = `Below average for ${useCase} installations`;
  }

  return { percentile, comparison };
}

/**
 * Quick validation check - returns simple yes/no if config is reasonable
 */
export async function validateConfiguration(
  input: AIOptimizationInput
): Promise<{ isValid: boolean; warning?: string }> {
  try {
    const baseline = await calculateDatabaseBaseline(input.useCase, 1.0, input.useCaseData);
    const sizeDiffPercent =
      Math.abs((input.storageSizeMW - baseline.powerMW) / baseline.powerMW) * 100;

    if (sizeDiffPercent > 100) {
      return {
        isValid: false,
        warning: `⚠️ Configuration is ${sizeDiffPercent.toFixed(0)}% different from industry standard. Consider using the recommended ${baseline.powerMW}MW size.`,
      };
    }

    return { isValid: true };
  } catch (error) {
    return { isValid: true }; // Don't block on validation errors
  }
}

// AI State Management Service
// Provides persistent state tracking for AI optimization across sessions

export type AIState = "never-used" | "unselected" | "active" | "applied" | "analyzing";

export interface AISessionData {
  state: AIState;
  lastUsed?: number; // timestamp
  appliedConfig?: string;
  sessionId?: string;
  usageCount: number;
}

class AIStateService {
  private readonly STORAGE_KEY = "merlin_ai_state";
  private readonly SESSION_DURATION = 24 * 60 * 60 * 1000; // 24 hours

  // Get current AI state
  getAIState(): AISessionData {
    try {
      const stored = localStorage.getItem(this.STORAGE_KEY);
      if (stored) {
        const data: AISessionData = JSON.parse(stored);

        // Check if session is still valid (within 24 hours)
        const now = Date.now();
        if (data.lastUsed && now - data.lastUsed > this.SESSION_DURATION) {
          // Session expired, reset to never-used but keep usage count
          return {
            state: "never-used",
            usageCount: data.usageCount || 0,
          };
        }

        return data;
      }
    } catch (error) {
      console.warn("Failed to load AI state from localStorage:", error);
    }

    // Default state for new users
    return {
      state: "never-used",
      usageCount: 0,
    };
  }

  // Update AI state
  setAIState(state: AIState, additionalData?: Partial<AISessionData>): void {
    try {
      const currentData = this.getAIState();
      const newData: AISessionData = {
        ...currentData,
        state,
        lastUsed: Date.now(),
        ...additionalData,
      };

      // Increment usage count when AI is applied
      if (state === "applied") {
        newData.usageCount = (currentData.usageCount || 0) + 1;
      }

      localStorage.setItem(this.STORAGE_KEY, JSON.stringify(newData));
    } catch (error) {
      console.warn("Failed to save AI state to localStorage:", error);
    }
  }

  // Check if user has used AI before
  hasUsedAIBefore(): boolean {
    const data = this.getAIState();
    return data.usageCount > 0;
  }

  // Get usage count
  getUsageCount(): number {
    const data = this.getAIState();
    return data.usageCount || 0;
  }

  // Clear AI state (for testing or reset)
  clearAIState(): void {
    try {
      localStorage.removeItem(this.STORAGE_KEY);
    } catch (error) {
      console.warn('Failed to clear AI state from localStorage:', error);
    }
  }

  // Reset AI state for new wizard session (preserve usage count for analytics)
  resetForNewSession(): void {
    try {
      const currentData = this.getAIState();
      const resetData: AISessionData = {
        state: "never-used",
        usageCount: currentData.usageCount || 0, // Preserve usage count for user experience
        lastUsed: undefined,
        appliedConfig: undefined,
        sessionId: undefined,
      };
      localStorage.setItem(this.STORAGE_KEY, JSON.stringify(resetData));
    } catch (error) {
      console.warn('Failed to reset AI state in localStorage:', error);
    }
  }

  // Get state-based button styling
  getButtonStyling(currentState?: AIState): {
    className: string;
    text: string;
    icon: string;
    description: string;
  } {
    const state = currentState || this.getAIState().state;
    const usageCount = this.getUsageCount();

    switch (state) {
      case "never-used":
      case "unselected":
        return {
          className:
            usageCount > 0
              ? "bg-white text-purple-600 border-2 border-purple-300 hover:bg-purple-50 hover:border-purple-400"
              : "bg-gradient-to-r from-purple-600 to-blue-600 text-white border-2 border-transparent hover:from-purple-700 hover:to-blue-700",
          text: usageCount > 0 ? "Use AI Again" : "Try AI Optimization",
          icon: "🤖",
          description:
            usageCount > 0 ? "Get additional AI insights" : "Let AI analyze your configuration",
        };

      case "analyzing":
        return {
          className:
            "bg-gradient-to-r from-blue-600 to-purple-600 text-white border-2 border-blue-300 ring-4 ring-blue-200",
          text: "AI Analyzing...",
          icon: "🔍",
          description: "AI is analyzing your configuration",
        };

      case "active":
        return {
          className:
            "bg-gradient-to-r from-blue-600 to-purple-600 text-white border-2 border-blue-300 ring-4 ring-blue-200",
          text: "AI Analysis Ready",
          icon: "⚡",
          description: "AI has suggestions ready to apply",
        };

      case "applied":
        return {
          className:
            "bg-gradient-to-r from-green-600 to-emerald-600 text-white border-2 border-green-300 ring-4 ring-green-200",
          text: "✅ AI Applied",
          icon: "✅",
          description: "AI optimization has been applied",
        };

      default:
        return {
          className:
            "bg-gradient-to-r from-purple-600 to-blue-600 text-white border-2 border-transparent hover:from-purple-700 hover:to-blue-700",
          text: "Try AI Optimization",
          icon: "🤖",
          description: "Let AI analyze your configuration",
        };
    }
  }

  // Get contextual messaging based on usage history
  getContextualMessage(): string {
    const usageCount = this.getUsageCount();
    const state = this.getAIState().state;

    if (usageCount === 0) {
      return "Let our AI analyze your configuration and suggest optimizations based on industry best practices.";
    } else if (usageCount === 1) {
      return "Want additional insights? Our AI can provide alternative configurations or refinements.";
    } else {
      return `You've used AI optimization ${usageCount} times. Each analysis can reveal new insights as your requirements evolve.`;
    }
  }
}

