/**
 * Generate comprehensive BESS recommendation for a specific use case
 */
export function generateBESSRecommendation(params: {
  useCase: string;
  facilitySize: number; // Units depend on use case (rooms, sq ft, bays, etc.)
  location: string;
  electricityRate?: number;
  demandCharge?: number;
  objective?: "peak-shaving" | "backup" | "arbitrage" | "all";
}): {
  sizing: BESSSizingParameters;
  financials: ReturnType<typeof calculateBESSFinancials>;
  profile: UseCaseEnergyProfile;
  insights: string[];
} {
  const { useCase, facilitySize, electricityRate, demandCharge, objective = "all" } = params;

  // Get use case profile
  const profile = USE_CASE_ENERGY_PROFILES[useCase] || USE_CASE_ENERGY_PROFILES["retail"];

  // Calculate facility energy characteristics
  const peakDemandkW = facilitySize * profile.peakDemandkW;
  const averageDemandkW = facilitySize * profile.averageDemandkW;
  const dailyEnergyConsumptionkWh = (facilitySize * profile.annualEnergyConsumptionkWh) / 365;

  // Calculate BESS sizing
  const sizing = calculateBESSSize({
    peakDemandkW,
    averageDemandkW,
    dailyEnergyConsumptionkWh,
    useCase,
    primaryObjective: objective,
  });

  // Calculate financials
  const financialInputs: BESSFinancialInputs = {
    ...DEFAULT_BESS_FINANCIAL_INPUTS,
    powerRatingMW: sizing.recommendedPowerMW,
    durationHours: sizing.recommendedDurationHours,
    electricityRatePerMWh: electricityRate || profile.averageElectricityRatePerMWh,
    demandChargePerMWPerMonth: demandCharge || profile.averageDemandChargePerMWPerMonth,
  };

  const financials = calculateBESSFinancials(financialInputs);

  // Generate insights
  const insights = [
    `Peak shaving potential: ${profile.peakShavingPotentialPercent}% reduction (${((peakDemandkW * profile.peakShavingPotentialPercent) / 100 / 1000).toFixed(2)} MW)`,
    `Estimated demand charge savings: ${profile.demandChargeReductionPercent}% ($${((profile.averageDemandChargePerMWPerMonth * 12 * sizing.recommendedPowerMW * profile.demandChargeReductionPercent) / 100).toLocaleString()}/year)`,
    `Energy arbitrage opportunity: ${profile.energyArbitragePotentialPercent}% savings`,
    `Recommended backup duration: ${profile.backupPowerHoursRequired} hours`,
    `System payback: ${financials.paybackYears.toFixed(1)} years`,
    `NPV over ${financialInputs.projectLifetimeYears} years: $${financials.netPresentValue.toLocaleString()}`,
  ];

  return {
    sizing,
    financials,
    profile,
    insights,
  };
}

/**
 * BRAND PRESET SERVICE
 * ====================
 *
 * Loads brand/chain-specific equipment defaults from database.
 * Used to pre-fill equipment values when user selects a brand in Step 3.
 *
 * Phase 3: Universal structural changes for all use cases
 */

import { supabase } from "./supabaseClient";

export interface BrandPreset {
  id: string;
  brandName: string;
  brandSlug: string;
  description?: string;
  logoUrl?: string;
  equipmentDefaults: Record<string, any>;
}

/**
 * Get all brands for a use case
 */
export async function getBrandsForUseCase(useCaseSlug: string): Promise<BrandPreset[]> {
  try {
    const { data, error } = await supabase
      .from("use_case_brands")
      .select(
        `
        id,
        brand_name,
        brand_slug,
        description,
        logo_url,
        equipment_defaults
      `
      )
      .eq("is_active", true)
      .order("brand_name", { ascending: true });

    if (error) {
      console.error("Error fetching brands:", error);
      return [];
    }

    // Filter by use case slug (we need to join with use_cases table)
    // For now, we'll filter client-side after fetching
    // TODO: Add proper join in query for better performance
    const { data: useCase, error: useCaseError } = await supabase
      .from("use_cases")
      .select("id")
      .eq("slug", useCaseSlug)
      .single();

    if (useCaseError || !useCase) {
      console.error("Error finding use case:", useCaseError);
      return [];
    }

    const { data: brands, error: brandsError } = await supabase
      .from("use_case_brands")
      .select(
        `
        id,
        brand_name,
        brand_slug,
        description,
        logo_url,
        equipment_defaults
      `
      )
      .eq("use_case_id", useCase.id)
      .eq("is_active", true)
      .order("brand_name", { ascending: true });

    if (brandsError) {
      console.error("Error fetching brands:", brandsError);
      return [];
    }

    return (brands || []).map((brand) => ({
      id: brand.id,
      brandName: brand.brand_name,
      brandSlug: brand.brand_slug,
      description: brand.description || undefined,
      logoUrl: brand.logo_url || undefined,
      equipmentDefaults: brand.equipment_defaults || {},
    }));
  } catch (err) {
    console.error("Error in getBrandsForUseCase:", err);
    return [];
  }
}

/**
 * Get brand preset by slug
 */
export async function getBrandPreset(
  useCaseSlug: string,
  brandSlug: string
): Promise<BrandPreset | null> {
  try {
    const { data: useCase, error: useCaseError } = await supabase
      .from("use_cases")
      .select("id")
      .eq("slug", useCaseSlug)
      .single();

    if (useCaseError || !useCase) {
      console.error("Error finding use case:", useCaseError);
      return null;
    }

    const { data: brand, error: brandError } = await supabase
      .from("use_case_brands")
      .select(
        `
        id,
        brand_name,
        brand_slug,
        description,
        logo_url,
        equipment_defaults
      `
      )
      .eq("use_case_id", useCase.id)
      .eq("brand_slug", brandSlug)
      .eq("is_active", true)
      .single();

    if (brandError || !brand) {
      console.error("Error fetching brand preset:", brandError);
      return null;
    }

    return {
      id: brand.id,
      brandName: brand.brand_name,
      brandSlug: brand.brand_slug,
      description: brand.description || undefined,
      logoUrl: brand.logo_url || undefined,
      equipmentDefaults: brand.equipment_defaults || {},
    };
  } catch (err) {
    console.error("Error in getBrandPreset:", err);
    return null;
  }
}

/**
 * Apply brand preset defaults to use case data
 *
 * This function takes brand equipment defaults and applies them to
 * the use case data object, filling in values that aren't already set.
 */
export function applyBrandPresetDefaults(
  useCaseData: Record<string, any>,
  brandPreset: BrandPreset
): Record<string, any> {
  const defaults = brandPreset.equipmentDefaults;
  const updated = { ...useCaseData };

  // Apply defaults for car wash pumps
  if (defaults.pumpTypes) {
    if (defaults.pumpTypes.highPressure?.count) {
      updated.highPressurePumpCount = defaults.pumpTypes.highPressure.count;
    }
    if (defaults.pumpTypes.chemicalApplication?.count) {
      updated.chemicalPumpCount = defaults.pumpTypes.chemicalApplication.count;
    }
    if (defaults.pumpTypes.supportUtilities?.count) {
      updated.supportPumpCount = defaults.pumpTypes.supportUtilities.count;
    }
  }

  // Apply defaults for car wash dryers
  if (defaults.dryers) {
    if (defaults.dryers.count) {
      updated.dryerCount = defaults.dryers.count;
    }
    if (defaults.dryers.type) {
      updated.dryerType = defaults.dryers.type;
    }
  }

  // Apply defaults for car wash vacuum stations
  if (defaults.vacuumStations?.count) {
    updated.vacuumStationCount = defaults.vacuumStations.count;
  }

  // Apply hotel defaults
  if (defaults.roomCount?.typical) {
    updated.roomCount = defaults.roomCount.typical;
  }
  if (defaults.diningFacilities) {
    if (defaults.diningFacilities.restaurants) {
      updated.restaurantCount = defaults.diningFacilities.restaurants;
    }
    if (defaults.diningFacilities.bars) {
      updated.barCount = defaults.diningFacilities.bars;
    }
  }
  if (defaults.amenities) {
    if (defaults.amenities.pool !== undefined) {
      updated.hasPool = defaults.amenities.pool;
    }
    if (defaults.amenities.gym !== undefined) {
      updated.hasGym = defaults.amenities.gym;
    }
    if (defaults.amenities.spa !== undefined) {
      updated.hasSpa = defaults.amenities.spa;
    }
  }

  return updated;
}

/**
 * Simple In-Memory Cache Service
 *
 * Provides caching for frequently accessed data like baseline configurations.
 * Reduces database queries and improves performance.
 *
 * Features:
 * - TTL (Time-To-Live) expiration
 * - LRU (Least Recently Used) eviction
 * - Size limits
 * - Cache statistics
 */

interface CacheEntry<T> {
  data: T;
  timestamp: number;
  hits: number;
}

interface CacheStats {
  hits: number;
  misses: number;
  size: number;
  hitRate: number;
}

class CacheService {
  private cache: Map<string, CacheEntry<any>>;
  private maxSize: number;
  private defaultTTL: number; // milliseconds
  private stats: { hits: number; misses: number };

  constructor(maxSize: number = 100, defaultTTL: number = 5 * 60 * 1000) {
    this.cache = new Map();
    this.maxSize = maxSize;
    this.defaultTTL = defaultTTL; // Default: 5 minutes
    this.stats = { hits: 0, misses: 0 };
  }

  /**
   * Get value from cache
   */
  get<T>(key: string): T | null {
    const entry = this.cache.get(key);

    if (!entry) {
      this.stats.misses++;
      return null;
    }

    // Check if expired
    const now = Date.now();
    const age = now - entry.timestamp;

    if (age > this.defaultTTL) {
      this.cache.delete(key);
      this.stats.misses++;
      return null;
    }

    // Update hit count and move to end (LRU)
    entry.hits++;
    this.stats.hits++;

    // Re-insert to update position
    this.cache.delete(key);
    this.cache.set(key, entry);

    return entry.data as T;
  }

  /**
   * Set value in cache
   */
  set<T>(key: string, data: T, ttl?: number): void {
    // Evict oldest entry if at capacity
    if (this.cache.size >= this.maxSize && !this.cache.has(key)) {
      const firstKey = this.cache.keys().next().value;
      if (firstKey) {
        this.cache.delete(firstKey);
      }
    }

    this.cache.set(key, {
      data,
      timestamp: Date.now(),
      hits: 0,
    });
  }

  /**
   * Delete value from cache
   */
  delete(key: string): boolean {
    return this.cache.delete(key);
  }

  /**
   * Clear specific pattern (e.g., all baseline calculations)
   */
  clearPattern(pattern: string): number {
    let cleared = 0;
    const regex = new RegExp(pattern);

    for (const key of this.cache.keys()) {
      if (regex.test(key)) {
        this.cache.delete(key);
        cleared++;
      }
    }

    return cleared;
  }

  /**
   * Clear all cache
   */
  clear(): void {
    this.cache.clear();
    this.stats = { hits: 0, misses: 0 };
  }

  /**
   * Get cache statistics
   */
  getStats(): CacheStats {
    const total = this.stats.hits + this.stats.misses;
    return {
      hits: this.stats.hits,
      misses: this.stats.misses,
      size: this.cache.size,
      hitRate: total > 0 ? (this.stats.hits / total) * 100 : 0,
    };
  }

  /**
   * Get all cache keys (for debugging)
   */
  getKeys(): string[] {
    return Array.from(this.cache.keys());
  }

  /**
   * Prune expired entries
   */
  prune(): number {
    const now = Date.now();
    let pruned = 0;

    for (const [key, entry] of this.cache.entries()) {
      const age = now - entry.timestamp;
      if (age > this.defaultTTL) {
        this.cache.delete(key);
        pruned++;
      }
    }

    return pruned;
  }
}

// Create singleton instances for different data types
export const baselineCache = new CacheService(50, 10 * 60 * 1000); // 10 min TTL, 50 entries
export const useCaseCache = new CacheService(100, 30 * 60 * 1000); // 30 min TTL, 100 entries
export const calculationCache = new CacheService(200, 5 * 60 * 1000); // 5 min TTL, 200 entries

// Auto-prune every 5 minutes
setInterval(
  () => {
    baselineCache.prune();
    useCaseCache.prune();
    calculationCache.prune();
  },
  5 * 60 * 1000
);

// Export cache service class for custom instances
export default CacheService;

