      patterns: [
        "project",
        "install",
        "deploy",
        "construction",
        "development",
        "announcement",
        "commission",
        "operational",
      ],
      score: 0.15,
    },
    {
      topic: "policy",
      patterns: [
        "regulation",
        "policy",
        "incentive",
        "itc",
        "tax credit",
        "rebate",
        "subsidy",
        "government",
        "federal",
        "state",
        "legislation",
        "bill",
      ],
      score: 0.2,
    },
    {
      topic: "tariffs",
      patterns: ["tariff", "trade", "import", "export", "duty", "customs", "trade war"],
      score: 0.2,
    },
    {
      topic: "market-trends",
      patterns: [
        "market",
        "forecast",
        "outlook",
        "trend",
        "growth",
        "decline",
        "demand",
        "supply",
        "capacity",
        "industry",
      ],
      score: 0.15,
    },
    {
      topic: "technology",
      patterns: [
        "technology",
        "innovation",
        "breakthrough",
        "advancement",
        "new tech",
        "cutting edge",
        "next generation",
        "patent",
      ],
      score: 0.1,
    },
    {
      topic: "financing",
      patterns: [
        "financing",
        "funding",
        "investment",
        "capital",
        "loan",
        "lease",
        "ppa",
        "power purchase agreement",
        "financier",
      ],
      score: 0.15,
    },
    {
      topic: "manufacturing",
      patterns: [
        "manufacture",
        "factory",
        "production",
        "facility",
        "plant",
        "assembly",
        "supply chain",
      ],
      score: 0.1,
    },
    {
      topic: "grid",
      patterns: [
        "grid",
        "utility",
        "transmission",
        "distribution",
        "interconnection",
        "net metering",
        "grid-tied",
      ],
      score: 0.15,
    },
    {
      topic: "sustainability",
      patterns: [
        "sustainability",
        "carbon",
        "emission",
        "renewable",
        "clean energy",
        "green",
        "climate",
        "environmental",
      ],
      score: 0.1,
    },
    {
      topic: "performance",
      patterns: [
        "efficiency",
        "performance",
        "output",
        "capacity",
        "rating",
        "specification",
        "specs",
        "warranty",
      ],
      score: 0.1,
    },
    {
      topic: "partnership",
      patterns: [
        "partnership",
        "collaboration",
        "joint venture",
        "alliance",
        "agreement",
        "deal",
        "contract",
      ],
      score: 0.1,
    },
  ];

  // Detect topics with improved matching
  for (const { topic, patterns, score } of topicPatterns) {
    const matches = patterns.filter((pattern) => {
      // Use word boundary for better matching - escape special regex chars
      const escapedPattern = pattern.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
      const regex = new RegExp("\\b" + escapedPattern + "\\b", "i");
      return regex.test(textLower);
