  return INDUSTRY_NEWS_SOURCES.map((source: any) => ({
    name: source.name,
    url: source.url,
    categories: source.category.join(", "),
    subscriptionRequired: source.subscriptionRequired,
    apiAvailable: source.apiAvailable,
  }));
}

