/**
 * Get Peak Sun Hours for a location
 * Data source: NREL PVWatts Calculator (worst month design)
 *
 * Design philosophy: Size for worst month to ensure year-round operation
 */
export function getPeakSunHours(location: string): number {
  const locationLower = location.toLowerCase();

  // US Cities (worst month PSH)
  const pshDatabase: Record<string, number> = {
    // California
    "los angeles": 4.5,
    "san francisco": 4.0,
    "san diego": 5.0,
    sacramento: 3.5,
    fresno: 3.8,

    // Southwest
    phoenix: 5.5,
    "las vegas": 5.2,
    tucson: 5.3,
    albuquerque: 5.0,

    // Texas
    houston: 3.8,
    dallas: 4.0,
    austin: 4.2,
    "san antonio": 4.3,

    // Southeast
    miami: 4.5,
    atlanta: 3.5,
    tampa: 4.2,
    charlotte: 3.8,

    // Northeast
    "new york": 3.2,
    boston: 3.0,
    philadelphia: 3.3,
    washington: 3.5,

    // Midwest
    chicago: 3.0,
    denver: 4.5,
    minneapolis: 3.2,
    "kansas city": 3.8,

    // Northwest
    seattle: 2.5,
    portland: 2.8,
    boise: 3.5,

    // Default by state (if city not found)
    california: 4.0,
    arizona: 5.2,
    texas: 4.0,
    florida: 4.0,
    nevada: 5.0,
    "new mexico": 5.0,
    colorado: 4.5,
  };

  // Try to find city match
  for (const [key, psh] of Object.entries(pshDatabase)) {
    if (locationLower.includes(key)) {
      return psh;
    }
  }

  // Default: Conservative estimate for unknown locations
  console.warn(`⚠️  Location "${location}" not in database, using default PSH = 3.5`);
  return 3.5;
}

