 * 3. equipment_pricing table (vendor-specific, synced)
 * 4. Market data integration (RSS/web sources)
 * 5. NREL ATB 2024/2025 fallback constants
 */
async function fetchBatteryPricingFromDB(
  powerMW: number,
  durationHours: number,
  location: string = "United States"
): Promise<BatteryPricing> {
  const energyMWh = powerMW * durationHours;
  const energyKWh = energyMWh * 1000;

  try {
    // PRIORITY 1: Try vendor pricing (approved vendor products)
    const vendorPricing = await getVendorPricing("bess", energyKWh, powerMW * 1000);
    if (vendorPricing && vendorPricing.pricePerKwh) {
      if (import.meta.env.DEV) {
        console.log(
          `🏢 Battery pricing from VENDOR: $${vendorPricing.pricePerKwh}/kWh (${vendorPricing.manufacturer} ${vendorPricing.model})`
        );
      }

      // Apply size-based adjustments if needed
      let adjustedPrice = vendorPricing.pricePerKwh;
      if (energyMWh >= 100) {
        adjustedPrice = adjustedPrice * 0.85; // Utility-scale discount
      } else if (energyMWh < 20) {
        adjustedPrice = adjustedPrice * 1.3; // Small system premium
      }

      return {
        pricePerKWh: Math.round(adjustedPrice),
        manufacturer: vendorPricing.manufacturer,
        model: vendorPricing.model,
        chemistry: "LFP", // Default, could be enhanced
        warrantyYears: vendorPricing.warrantyYears,
        cycleLife: 4000, // Default
        efficiency: 0.85, // Default
        dataSource: "database", // Vendor pricing stored in database
        lastUpdated: vendorPricing.approvedAt,
        confidence: "high",
      };
    }

    // PRIORITY 2: Try calculation_constants table (database SSOT)
    let pricePerKWh: number | null = null;
    const dataSource: "database" | "nrel" = "database";

    if (energyKWh >= 10000) {
      // 10+ MWh = large utility scale
      pricePerKWh = await getConstant("battery_cost_per_kwh_large");
    } else if (energyKWh >= 1000) {
      // 1-10 MWh = commercial scale
      pricePerKWh = await getConstant("battery_cost_per_kwh_medium");
    } else {
      // < 1 MWh = small/SMB scale
      pricePerKWh = await getConstant("battery_cost_per_kwh_small");
    }

    // If we got a value from calculation_constants, use it
    if (pricePerKWh !== null) {
      if (import.meta.env.DEV) {
        console.log(
          `💾 Battery pricing from calculation_constants: $${pricePerKWh}/kWh (${energyKWh.toFixed(0)} kWh system)`
        );
      }
      return {
        pricePerKWh,
        manufacturer:
          energyKWh >= 10000 ? "CATL/BYD" : energyKWh >= 1000 ? "Great Power" : "LiON Energy",
        model:
          energyKWh >= 10000
            ? "Utility Scale LFP"
            : energyKWh >= 1000
              ? "Commercial Container"
              : "Small Commercial",
        chemistry: "LFP",
        warrantyYears: 10,
        cycleLife: 4000,
        efficiency: 0.85,
        dataSource: "database",
        lastUpdated: new Date(),
        confidence: "high",
      };
    }

    // PRIORITY 2: Try equipment_pricing table (vendor-specific)
    const { data, error } = await supabase
      .from("equipment_pricing")
      .select("*")
      .eq("equipment_type", "battery")
      .eq("is_active", true)
      .order("updated_at", { ascending: false })
      .limit(1)
      .maybeSingle();

    if (!error && data) {
      // Size-based adjustments from vendor pricing
      let vendorPrice = data.price_per_kwh || NREL_ATB_2024_BATTERY.pricePerKWh;

      if (energyMWh >= 100) {
        // Utility-scale discount
        vendorPrice = vendorPrice * 0.85;
      } else if (energyMWh < 20) {
        // Small system premium
        vendorPrice = vendorPrice * 1.3;
      }

      if (import.meta.env.DEV) {
        console.log(
          `💾 Battery pricing from equipment_pricing: $${vendorPrice.toFixed(0)}/kWh (${data.manufacturer})`
        );
      }

      return {
        pricePerKWh: Math.round(vendorPrice),
        manufacturer: data.manufacturer || "Various",
        model: data.model || "Commercial LFP",
        chemistry: "LFP",
        warrantyYears: 10,
        cycleLife: 4000,
        efficiency: 0.85,
        dataSource: "database",
        lastUpdated: new Date(data.updated_at),
        confidence: "high",
      };
    }

    // PRIORITY 3: Try MARKET DATA INTEGRATION (scraped from RSS/web sources)
    // This uses the daily market scraper for real-time pricing intelligence
    const marketData = await getMarketAdjustedPrice(
      "bess",
      NREL_ATB_2024_BATTERY.pricePerKWh,
      location
    );

    if (marketData.source === "market" && marketData.confidence !== "low") {
      if (import.meta.env.DEV) {
        console.log(
          `📈 Battery pricing from MARKET DATA: $${marketData.price}/kWh (${marketData.confidence} confidence, ${marketData.dataPoints || 0} data points)`
        );
        if (marketData.marketTrend) {
          console.log(`   Market trend: ${marketData.marketTrend}`);
        }
      }

      return {
        pricePerKWh: Math.round(marketData.price),
        manufacturer: "Various (Market Intelligence)",
        model:
          energyKWh >= 10000
            ? "Utility Scale LFP"
            : energyKWh >= 1000
              ? "Commercial Container"
              : "Small Commercial",
        chemistry: "LFP",
        warrantyYears: 10,
        cycleLife: 4000,
        efficiency: 0.85,
        dataSource: "database",
        lastUpdated: new Date(),
        confidence: marketData.confidence,
      };
    }

    // PRIORITY 4: Fall back to NREL constants
    if (import.meta.env.DEV) {
      console.log(
        `📦 Battery pricing from NREL fallback: $${NREL_ATB_2024_BATTERY.pricePerKWh}/kWh`
      );
    }
    return NREL_ATB_2024_BATTERY;
  } catch (error: any) {
    // Silently fall back for missing tables (expected in dev)
    if (!error?.message?.includes("relation") && !error?.message?.includes("does not exist")) {
      console.warn("⚠️ Database fetch failed:", error);
    }
    return NREL_ATB_2024_BATTERY;
  }
}

