export function getQuestionsForWarehouse(warehouseType?: string): typeof WAREHOUSE_QUESTIONS {
  if (!warehouseType) {
    return WAREHOUSE_QUESTIONS;
  }

  // Filter questions based on warehouse type and conditionals
  return WAREHOUSE_QUESTIONS.filter((q) => {
    if (!q.conditional) return true;

    const cond = q.conditional;

    // Handle field value conditions
    if ("field" in cond && "value" in cond) {
      // UI handles conditional display
      return true;
    }

    if ("field" in cond && "values" in cond) {
      return true;
    }

    if ("notValue" in cond) {
      return true;
    }

    if ("min" in cond) {
      return true;
    }

    return true;
  }) as typeof WAREHOUSE_QUESTIONS;
}

import { Paragraph, TextRun, TableRow, TableCell } from "docx";

/**
 * Helper functions for Word document generation
 */

export function boldParagraph(text: string): Paragraph {
  return new Paragraph({
    children: [new TextRun({ text, bold: true })],
  });
}

export function italicParagraph(text: string, options: any = {}): Paragraph {
  return new Paragraph({
    children: [new TextRun({ text, italics: true })],
    ...options,
  });
}

export function createHeaderRow(headers: string[], color: string = "2563EB"): TableRow {
  return new TableRow({
    children: headers.map(
      (header) =>
        new TableCell({
          children: [boldParagraph(header)],
          shading: { fill: color },
        })
    ),
  });
}

export function createDataRow(data: string[]): TableRow {
  return new TableRow({
    children: data.map((item) => new TableCell({ children: [new Paragraph(item)] })),
  });
}

