  batterySubtotal: number;
  pcsSubtotal: number;
  bosAmount: number;
  epcAmount: number;
  bessCapEx: number;
  generatorSubtotal: number;
  solarSubtotal: number;
  windSubtotal: number;
  batteryTariff: number;
  otherTariff: number;
  totalTariffs: number;
